-- ============================================================
-- 0040 — Curadoria dos textos-base da RNC: Transversal SSMA/Gestão (MA/QA/EQ/DC/VE/SO/EM/CT/PR)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- CT-01 (9 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver documento vencido ou ausente que caracterize irregularidade fiscal/trabalhista com risco de responsabilização solidária da contratante, embargo ou impedimento de acesso do efetivo à obra.',
  texto_fundamentacao_normativa = 'A habilitação jurídica, fiscal e trabalhista da subcontratada é condição contratual para a permanência do prestador no canteiro. O critério do item — contrato assinado, Certidões Negativas de Débito (CNDs), apólices de seguro vigentes e comprovação de recolhimento de FGTS e INSS — decorre das obrigações previdenciárias e trabalhistas aplicáveis e da cláusula de habilitação do contrato de subcontratação, que transfere à contratante o dever de fiscalizar tais documentos sob pena de responsabilização solidária/subsidiária. Trata-se de requisito verificável de aceitação, integrante do plano de gestão de subcontratadas da obra, sem o qual não se admite a mobilização do prestador.',
  texto_risco_consequencia = 'A permanência de documentação legal vencida ou ausente expõe a contratante a responsabilização solidária por débitos trabalhistas e previdenciários da subcontratada, a autuações fiscais, à retenção de medições e ao risco de embargo ou paralisação da frente por irregularidade do prestador. Enquanto não regularizada, mantém-se ativo o passivo legal e o vínculo de risco entre as partes. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) notificar formalmente a subcontratada a apresentar os documentos regularizados (contrato, CNDs, apólices e guias de FGTS/INSS quitadas), com prazo definido; (ii) condicionar o acesso do efetivo e a liberação da próxima medição à comprovação da regularidade, retendo pagamentos enquanto persistir a pendência; (iii) evidenciar a correção com registro documental e fotográfico das certidões e comprovantes atualizados ({{evidencia_foto_correcao}}), arquivando-os no dossiê da subcontratada e submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CT-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — trabalhador sem integração admissional executando atividade caracteriza exposição a risco sem capacitação prévia; retirar imediatamente o colaborador da frente até a realização da integração.',
  texto_fundamentacao_normativa = 'A integração de 100% do efetivo antes do início das atividades assegura que todo trabalhador conheça os riscos do canteiro, as medidas de controle e os procedimentos de emergência antes de se expor a eles. Aplica-se a NR-18 (Segurança e Saúde no Trabalho na Indústria da Construção), que exige capacitação/treinamento admissional em segurança ao trabalhador da construção, complementada pela NR-1 quanto à obrigação geral de informação e treinamento sobre os riscos ocupacionais. O critério — registro da integração antes do início das atividades — é requisito verificável de aceitação e pré-condição de acesso à frente de serviço.',
  texto_risco_consequencia = 'Trabalhador não integrado atua sem conhecimento dos riscos específicos do canteiro, das rotas de fuga e das regras de convivência, elevando a probabilidade de acidente, de ato inseguro e de acionamento indevido de sistemas críticos; em caso de sinistro, a ausência do registro de integração agrava a responsabilização da obra e a caracterização de culpa. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de imediato da frente o(s) colaborador(es) sem integração e realizar a integração admissional pendente, com lista de presença assinada; (ii) revisar o controle de acesso para bloquear a entrada de efetivo não integrado, vinculando o crachá/liberação à conclusão do treinamento; (iii) evidenciar a correção com registro fotográfico da sessão de integração e da lista de presença ({{evidencia_foto_correcao}}), atualizando o dossiê e submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CT-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a apólice estiver vencida ou sem cobertura para a totalidade do efetivo em atividade, dada a exposição do trabalhador e o descumprimento de obrigação contratual/convencional.',
  texto_fundamentacao_normativa = 'A manutenção de seguro de vida e de acidentes pessoais vigente para todo o efetivo da subcontratada decorre, em regra, de obrigação estabelecida em convenção coletiva de trabalho da categoria e reforçada por cláusula do contrato de subcontratação, garantindo cobertura indenizatória ao trabalhador e a seus dependentes em caso de acidente ou óbito. O critério do item — apólice vigente — é requisito verificável de aceitação; a sua comprovação, mediante apólice e comprovante de pagamento do prêmio, integra a habilitação do prestador para atuar na obra.',
  texto_risco_consequencia = 'A ausência ou o vencimento da apólice deixa o trabalhador sem a cobertura devida diante de acidente ou óbito e expõe a contratante ao descumprimento de obrigação convencional/contratual, com risco de passivo trabalhista, ações indenizatórias e responsabilização por não fiscalizar a garantia exigida. A condição permanece crítica enquanto não restabelecida a vigência da cobertura. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) exigir da subcontratada a apresentação da apólice vigente e do comprovante de quitação do prêmio, cobrindo nominalmente todo o efetivo alocado; (ii) suspender a liberação de novas frentes/medições até a comprovação da cobertura, formalizando a exigência por notificação; (iii) evidenciar a correção com registro da apólice atualizada e da relação de segurados ({{evidencia_foto_correcao}}), arquivando no dossiê da subcontratada e submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CT-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — colaborador executando atividade de risco especial sem certificado válido para a função (altura, elétrica, espaço confinado, etc.) deve ser afastado da tarefa até a regularização do treinamento.',
  texto_fundamentacao_normativa = 'Cada função de risco exige capacitação específica e certificado válido antes da execução da atividade, conforme as Normas Regulamentadoras aplicáveis a cada caso — por exemplo, NR-35 para trabalho em altura, NR-10 para serviços em instalações elétricas e NR-33 para espaços confinados —, além da capacitação geral prevista na NR-18 para o trabalhador da construção. O critério do item — certificados válidos por função — é requisito verificável de aceitação: a matriz de treinamento deve cobrir 100% do efetivo por atividade desempenhada, com certificados dentro do prazo de validade e reciclagem em dia.',
  texto_risco_consequencia = 'A execução de atividade de risco por trabalhador sem certificação válida caracteriza exposição a risco grave e iminente sem capacitação, elevando a probabilidade de acidente de alta severidade (queda, choque, asfixia) e configurando descumprimento normativo passível de autuação, interdição da atividade e responsabilização em caso de sinistro. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) afastar da atividade o(s) colaborador(es) sem certificado válido e reprogramar/realizar o treinamento exigido pela NR aplicável à função, atualizando a matriz de capacitação; (ii) bloquear a alocação em tarefas de risco enquanto não regularizada a certificação, condicionando a liberação à validação documental; (iii) evidenciar a correção com registro dos certificados válidos e da matriz de treinamento atualizada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CT-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se for identificado trabalhador sem registro em CTPS/e-Social atuando na obra, por caracterizar informalidade e risco de responsabilização solidária da contratante.',
  texto_fundamentacao_normativa = 'O efetivo em atividade deve estar formalmente registrado e identificável, com correspondência entre a lista de presença/controle de acesso e o registro em CTPS e no e-Social, em cumprimento à legislação trabalhista (CLT) e às obrigações de registro do vínculo empregatício. O critério do item — lista de presença confrontada com registro em CTPS/e-Social — é requisito verificável de aceitação que combate a informalidade, o uso de terceiros não cadastrados e a presença de pessoas não autorizadas no canteiro, integrando o controle de acesso e a gestão de subcontratadas da obra.',
  texto_risco_consequencia = 'A presença de trabalhador não registrado ou não identificado no canteiro caracteriza informalidade, expõe a contratante a autuações e a reconhecimento de vínculo/responsabilização solidária, dificulta o controle de acesso e a rastreabilidade em emergências e fragiliza a apuração de responsabilidades em caso de acidente. A divergência permanece ativa até a completa conciliação entre efetivo presente e registro formal. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conciliar nominalmente a lista de presença/controle de acesso com os registros de CTPS e e-Social, identificando e bloqueando o acesso de qualquer pessoa sem vínculo comprovado; (ii) exigir da subcontratada a regularização do registro do efetivo divergente antes da continuidade das atividades; (iii) evidenciar a correção com o cotejo documental atualizado e o registro fotográfico da identificação (crachás/uniformes) do efetivo ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CT-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver serviço técnico ou atividade de risco em execução sem responsável técnico presente e sem ART regular, dada a ausência de responsabilização técnica pela frente.',
  texto_fundamentacao_normativa = 'A presença de responsável técnico ou encarregado habilitado, devidamente identificado e com Anotação de Responsabilidade Técnica (ART) recolhida, assegura a supervisão técnica e a responsabilização profissional pela execução dos serviços da subcontratada. A ART é regida pela Lei nº 6.496/1977 e pela regulamentação do sistema CONFEA/CREA, vinculando o profissional habilitado à obra. O critério do item — RT/encarregado identificado com ART — é requisito verificável de aceitação, condicionando a execução dos serviços à existência de comando técnico presente e formalmente responsável.',
  texto_risco_consequencia = 'A ausência de responsável técnico presente e de ART regular deixa a frente sem supervisão técnica qualificada e sem responsabilização profissional definida, elevando o risco de execução em desacordo com o projeto e as boas práticas, de decisões técnicas indevidas em campo e de indefinição de responsabilidades perante fiscalização e em caso de sinistro. A condição persiste enquanto não regularizada a presença e a habilitação do RT. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) exigir a designação e a presença efetiva do responsável técnico/encarregado habilitado na frente, com a respectiva ART recolhida e vinculada à obra; (ii) suspender a continuidade dos serviços técnicos sensíveis até a comprovação da supervisão e da ART regular; (iii) evidenciar a correção com registro da ART, da identificação do RT e de sua presença em campo ({{evidencia_foto_correcao}}), arquivando no dossiê e submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CT-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a atividade de risco estiver em execução sem APR, ou com APR que não contemple os perigos reais da tarefa, deixando a frente sem análise de risco válida.',
  texto_fundamentacao_normativa = 'As Análises Preliminares de Risco (APRs) elaboradas pela subcontratada devem identificar os perigos da tarefa, as medidas de controle e as condições de execução, alinhadas ao padrão e ao nível de exigência da contratante, garantindo uniformidade metodológica no canteiro. A elaboração de APR é boa prática consolidada de gestão de SSMA e, em atividades específicas como trabalho em altura, é expressamente exigida pela NR aplicável (NR-35). O critério do item — APRs alinhadas ao padrão da contratante — é requisito verificável de aceitação, condicionando a liberação da atividade à existência de APR adequada, específica e assinada pela equipe.',
  texto_risco_consequencia = 'APR ausente, genérica ou desalinhada do padrão da contratante deixa perigos sem identificação e sem medida de controle definida, elevando a probabilidade de acidente por risco não mapeado e comprometendo a liberação segura da atividade e a rastreabilidade das decisões de segurança. A exposição permanece até que a APR seja adequada e efetivamente aplicada em campo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revisar/elaborar a APR específica da tarefa alinhada ao padrão da contratante, contemplando os perigos reais, as medidas de controle e a assinatura da equipe executante; (ii) condicionar a liberação da atividade à validação da APR pelo SSMA da contratante e à divulgação em campo (DDS); (iii) evidenciar a correção com registro da APR aprovada e da sua aplicação na frente ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CT-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior em caso de reincidência mensal na omissão dos indicadores ou de ocultação de incidente/desvio relevante que deveria ter sido reportado.',
  texto_fundamentacao_normativa = 'O reporte mensal dos indicadores de SSMA — Horas-Homem Trabalhadas (HHT), incidentes/acidentes e desvios identificados — é requisito de gestão contratual que permite consolidar as estatísticas de segurança da obra, monitorar tendências e subsidiar a comunicação legal de acidentes quando aplicável. O critério do item — HHT, incidentes e desvios informados mensalmente — decorre do plano de gestão de SSMA e das obrigações de reporte previstas no contrato de subcontratação, constituindo requisito verificável de aceitação para acompanhamento do desempenho de segurança do prestador.',
  texto_risco_consequencia = 'A falta de reporte dos indicadores impede a consolidação das estatísticas de segurança, mascara a real exposição da frente, retarda a detecção de tendências de acidentes e pode ocultar incidentes e desvios que exigiriam tratativa imediata ou comunicação legal, fragilizando a gestão preventiva e a resposta da obra. A lacuna de informação persiste até a entrega e conciliação dos dados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) exigir da subcontratada o envio retroativo e regularizado dos indicadores (HHT, incidentes e desvios) no formato padrão da contratante; (ii) instituir rotina mensal de reporte com prazo e responsável definidos, integrando os dados ao consolidado de SSMA da obra; (iii) evidenciar a correção com o registro dos relatórios entregues e da planilha consolidada atualizada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CT-01' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se as não conformidades anteriores em aberto envolverem risco de segurança do trabalho não tratado ou reincidência de desvio já notificado.',
  texto_fundamentacao_normativa = 'O plano de ação de desvios assegura que as não conformidades identificadas em inspeções anteriores tenham tratativa formal, com ação corretiva, responsável e prazo, e que sejam efetivamente concluídas e verificadas, segundo a lógica de melhoria contínua (PDCA) da gestão da qualidade e de SSMA. O critério do item — tratativas das NCs anteriores concluídas — é requisito verificável de aceitação: exige o encerramento documentado dos desvios pretéritos, evitando a perpetuação de pendências e a reincidência dos mesmos problemas no canteiro.',
  texto_risco_consequencia = 'A ausência ou o não fechamento do plano de ação mantém as não conformidades anteriores em aberto, perpetuando desvios já identificados, favorecendo a reincidência e permitindo que riscos conhecidos sigam sem controle. A não conclusão das tratativas descaracteriza o processo de melhoria contínua e acumula passivo de pendências não resolvidas na frente. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar as não conformidades anteriores em aberto e estruturar/atualizar o plano de ação com ação corretiva, responsável e prazo para cada uma; (ii) executar e verificar as tratativas pendentes, priorizando as de maior risco, e registrar o encerramento de cada NC; (iii) evidenciar a correção com o plano de ação atualizado e as evidências de conclusão das tratativas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CT-01' and item_numero = 9;

-- DC-01 (11 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o colaborador sem ASO válido estiver alocado em atividade de risco grave e iminente (altura, espaço confinado, eletricidade ou içamento), situação que impõe afastamento imediato do posto.',
  texto_fundamentacao_normativa = 'O Atestado de Saúde Ocupacional (ASO) é o documento que atesta a aptidão do trabalhador para a função, exigido nos exames admissional, periódico, de retorno ao trabalho, de mudança de risco e demissional. A NR-07 (PCMSO) e o PCMSO da obra estabelecem a obrigatoriedade e a periodicidade dos exames, de modo que a permanência de efetivo em campo pressupõe ASO dentro da validade. O critério "admissional/periódico dentro da validade" integra o plano de inspeção documental da obra e constitui requisito verificável de liberação do trabalhador para o serviço.',
  texto_risco_consequencia = 'A presença de trabalhador sem ASO válido implica alocação de mão de obra sem aptidão médica atestada para a função, expondo o colaborador a agravos à saúde não monitorados e a empresa a autuação, embargo e responsabilização em caso de acidente ou doença ocupacional. Enquanto não regularizado, o efetivo permanece irregular perante a fiscalização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar nominalmente o efetivo em campo e confrontar com os ASO vigentes, identificando exames vencidos ou ausentes; (ii) providenciar de imediato os exames médicos ocupacionais pendentes e emitir os respectivos ASO, afastando do posto quem não estiver apto; (iii) evidenciar a regularização com os ASO válidos arquivados e registro fotográfico do quadro de controle ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de certificado recair sobre atividade de alto risco (NR-10, NR-33 ou NR-35) com o trabalhador já executando o serviço, exigindo paralisação imediata da frente.',
  texto_fundamentacao_normativa = 'A capacitação específica por atividade é requisito legal: NR-10 (segurança em instalações e serviços em eletricidade), NR-33 (espaço confinado), NR-35 (trabalho em altura), NR-12 (máquinas e equipamentos), NR-18 (indústria da construção) e NR-20 (inflamáveis e combustíveis) exigem treinamento com carga horária, conteúdo e validade definidos, conforme a função exercida. O certificado, com identificação do instrutor, conteúdo programático e data, é a evidência de que o trabalhador foi habilitado antes da execução. O critério "conforme função" integra o plano de inspeção documental e constitui requisito verificável de aptidão operacional.',
  texto_risco_consequencia = 'A atuação de trabalhador sem o treinamento exigido para a função significa execução de tarefa de risco sem habilitação, ampliando a probabilidade de acidente grave (choque elétrico, queda, asfixia, esmagamento ou incêndio) e sujeitando a obra a autuação e embargo da atividade. Persistindo a lacuna, mantém-se pessoal não habilitado exposto ao risco. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear função por função os treinamentos exigidos (NR-10, NR-33, NR-35, NR-12, NR-18, NR-20) e cruzar com os certificados existentes, listando as lacunas; (ii) suspender a alocação dos não habilitados e programar/realizar os treinamentos faltantes com validade vigente; (iii) arquivar os certificados de forma rastreável e evidenciar a regularização com registro fotográfico da matriz de treinamento e das listas de presença ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se identificado trabalhador em campo sem qualquer registro de integração, exigindo seu afastamento até a realização da capacitação admissional.',
  texto_fundamentacao_normativa = 'A integração de segurança (treinamento admissional) apresenta ao trabalhador os riscos da obra, as medidas de prevenção e as regras específicas do canteiro antes do início das atividades. A NR-01 (ordem de serviço e informação sobre riscos) e a NR-18 (treinamento admissional na indústria da construção) estabelecem essa obrigação de informar e capacitar previamente. O critério "registro de todos antes do 1º dia em campo" integra o plano de inspeção documental e constitui requisito verificável de liberação do ingresso no canteiro.',
  texto_risco_consequencia = 'Trabalhador que ingressa na frente sem integração desconhece os riscos específicos e os procedimentos de emergência do canteiro, elevando a probabilidade de acidentes por desconhecimento e afastando a possibilidade de defesa da empresa quanto ao dever de informar. Enquanto não houver registro completo, mantém-se pessoal não orientado em campo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a relação do efetivo ativo com as listas de presença da integração, apontando quem ingressou sem registro; (ii) realizar de imediato a integração dos pendentes e condicionar o acesso ao canteiro à sua conclusão; (iii) arquivar as listas de presença assinadas e evidenciar a regularização com registro fotográfico da sessão e do controle de acesso ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o produto sem FISPQ disponível for classificado como inflamável, tóxico ou corrosivo e estiver em manuseio sem que a equipe conheça as medidas de emergência.',
  texto_fundamentacao_normativa = 'A Ficha de Informações de Segurança de Produtos Químicos (FISPQ) reúne os perigos, as medidas de manuseio, o EPI, os primeiros socorros e as ações de emergência de cada produto. A NBR 14725 estabelece o conteúdo e o formato da FISPQ segundo o Sistema Globalmente Harmonizado (GHS), e a NR-26 trata da identificação e da informação sobre produtos químicos no ambiente de trabalho. O critério "disponíveis e conhecidas pelas equipes" integra o plano de inspeção documental e constitui requisito verificável da gestão de produtos químicos no canteiro.',
  texto_risco_consequencia = 'A indisponibilidade ou o desconhecimento da FISPQ impede o manuseio seguro e a resposta correta a vazamentos, contato ou intoxicação, ampliando a gravidade de eventuais acidentes químicos e comprometendo a atuação de primeiros socorros e da brigada. Enquanto não sanada, a lacuna mantém as equipes sem a informação de segurança do produto. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inventariar os produtos químicos em uso e verificar a existência e a atualidade da FISPQ de cada um, conforme NBR 14725; (ii) obter junto aos fornecedores as fichas faltantes, disponibilizá-las no ponto de uso e promover a divulgação/orientação às equipes; (iii) evidenciar a regularização com o arquivo das FISPQ e registro fotográfico das fichas disponíveis nas frentes e da orientação realizada ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de APR/PT rastreável referir-se a atividade que exige permissão de trabalho formal (espaço confinado ou altura), evidenciando execução sem liberação documentada.',
  texto_fundamentacao_normativa = 'A Análise Preliminar de Risco (APR) e a Permissão de Trabalho (PT) formalizam a identificação dos riscos e a liberação da tarefa antes da execução, com validade e assinaturas dos responsáveis. Para atividades específicas, a PT é exigência normativa expressa — NR-33 (espaço confinado) e NR-35 (trabalho em altura) —, e as demais frentes seguem o procedimento de gestão de segurança da obra. O critério "rastreáveis por frente e data" integra o plano de inspeção documental e constitui requisito verificável de controle e evidência das liberações.',
  texto_risco_consequencia = 'A ausência de APR e PT arquivadas e rastreáveis impede comprovar que os riscos foram avaliados e a atividade liberada, sinalizando possível execução sem análise prévia e fragilizando a investigação de acidentes e a defesa da empresa. Persistindo, perde-se o rastro documental das liberações por frente e data. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar as frentes ativas e verificar a existência de APR e PT correspondentes, identificando lacunas e documentos não rastreáveis; (ii) restabelecer a emissão e o arquivamento organizados por frente e data, condicionando a liberação das tarefas à sua elaboração prévia; (iii) evidenciar a correção com o arquivo estruturado e registro fotográfico dos documentos e do controle ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o PGR ou o PCMSO estiverem vencidos ou ausentes, ou quando a incoerência entre eles omitir risco relevante da obra sem controle definido.',
  texto_fundamentacao_normativa = 'O Programa de Gerenciamento de Riscos (PGR), exigido pela NR-01, e o Programa de Controle Médico de Saúde Ocupacional (PCMSO), exigido pela NR-07, são os documentos-base da gestão de SST: o PGR inventaria os riscos e define o plano de ação, e o PCMSO define o controle médico decorrente desses riscos, devendo ser coerentes entre si. O critério "atualizados e coerentes entre si" integra o plano de inspeção documental e constitui requisito verificável da estrutura de gestão de segurança e saúde da obra.',
  texto_risco_consequencia = 'PGR e PCMSO desatualizados ou incoerentes significam gestão de SST sem base técnica válida: riscos não inventariados ficam sem controle e exames médicos podem não cobrir as exposições reais, comprometendo a prevenção e sujeitando a obra a autuação. Enquanto não harmonizados, os documentos-base permanecem inconsistentes. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a vigência do PGR (NR-01) e do PCMSO (NR-07) e confrontar os riscos inventariados com os controles médicos previstos, listando divergências; (ii) revisar e atualizar os documentos, assegurando coerência entre o inventário de riscos e o controle médico; (iii) evidenciar a regularização com as versões vigentes assinadas pelos responsáveis técnicos e registro do protocolo/arquivo ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a obra estiver em operação sem Licença de Operação/Instalação vigente ou sem alvará de execução, condição que expõe a atividade a embargo e paralisação.',
  texto_fundamentacao_normativa = 'As licenças ambientais (Licença de Instalação e Licença de Operação) e o alvará de execução da obra, além das licenças específicas aplicáveis (supressão vegetal, outorga de uso da água, intervenção em faixa de domínio, entre outras), condicionam a legalidade da implantação e operação do empreendimento. O licenciamento ambiental é disciplinado pela Política Nacional do Meio Ambiente (Lei nº 6.938/1981) e pela Resolução CONAMA nº 237/1997, e o alvará decorre da legislação municipal de obras. O critério "LI/LO, alvará da obra, licenças específicas" integra o plano de inspeção documental e constitui requisito verificável de regularidade legal do empreendimento.',
  texto_risco_consequencia = 'A execução sem licenças e alvará vigentes expõe o empreendimento a embargo, multa e paralisação pelos órgãos ambiental e municipal, além de responsabilização administrativa, civil e criminal por dano ambiental, com impacto direto no cronograma e no contrato. Enquanto pendente, a obra opera em situação de irregularidade legal. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) relacionar todas as licenças e alvarás exigíveis para a fase atual da obra e verificar vigência, condicionantes e abrangência; (ii) protocolar/renovar os documentos pendentes junto aos órgãos competentes e atender às condicionantes, suspendendo as atividades não licenciadas; (iii) evidenciar a regularização com as licenças e alvarás vigentes e registro do protocolo/publicação ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o equipamento sem laudo/certificação válida estiver em uso em içamento de carga, sustentação de trabalhadores (andaime) ou operação sob pressão, exigindo interdição imediata.',
  texto_fundamentacao_normativa = 'A certificação e os laudos de equipamentos atestam a integridade e a segurança operacional: vasos de pressão e caldeiras seguem a NR-13 (inspeções e prontuário), guindastes e demais equipamentos de içamento seguem a NR-11 e a NR-18, e os andaimes seguem os requisitos de projeto e inspeção da NR-18. Os laudos, com responsável técnico e validade, comprovam a aptidão do equipamento para uso. O critério "laudos de guindaste, andaime, vasos de pressão" integra o plano de inspeção documental e constitui requisito verificável de liberação dos equipamentos.',
  texto_risco_consequencia = 'A operação de equipamento sem laudo ou com certificação vencida significa uso de item cuja integridade não está atestada, elevando o risco de colapso estrutural, tombamento de guindaste, queda de andaime ou ruptura de vaso de pressão, com potencial de acidente grave ou fatal. Enquanto não certificado, o equipamento permanece em uso sem garantia de segurança. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inventariar guindastes, andaimes, vasos de pressão e demais equipamentos críticos e verificar a existência e a validade dos respectivos laudos e certificados; (ii) interditar os equipamentos sem certificação válida e providenciar as inspeções/laudos pelos responsáveis técnicos habilitados; (iii) evidenciar a regularização com os laudos vigentes arquivados e registro fotográfico do equipamento identificado/liberado ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o instrumento sem calibração válida for o detector de gás usado na liberação de espaço confinado, cuja leitura incorreta pode autorizar acesso a atmosfera perigosa.',
  texto_fundamentacao_normativa = 'A calibração assegura que a leitura do instrumento é confiável e rastreável a padrões metrológicos. Para os detectores de gás, a NR-33 exige o monitoramento da atmosfera antes e durante o acesso a espaço confinado, o que pressupõe equipamento calibrado; para os demais instrumentos de medição, a confiabilidade depende de calibração com rastreabilidade metrológica (RBC/INMETRO) e periodicidade definida. O critério "detectores de gás, instrumentos de medição" integra o plano de inspeção documental e constitui requisito verificável de confiabilidade das medições.',
  texto_risco_consequencia = 'Instrumento descalibrado fornece leitura não confiável: um detector de gás sem calibração pode indicar atmosfera segura quando há deficiência de oxigênio ou presença de gás tóxico/inflamável, liberando indevidamente o acesso e expondo o trabalhador a asfixia, intoxicação ou explosão. Enquanto não calibrado, o equipamento mantém medições sem garantia de exatidão. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) relacionar os detectores de gás e os instrumentos de medição em uso e verificar a validade dos certificados de calibração; (ii) retirar de uso os instrumentos com calibração vencida e enviá-los para calibração em laboratório com rastreabilidade metrológica, substituindo-os no ínterim; (iii) evidenciar a regularização com os certificados vigentes arquivados e registro fotográfico do instrumento com etiqueta de calibração ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a atividade técnica de execução ou fiscalização estiver em andamento sem ART recolhida, caracterizando ausência de responsável técnico legalmente vinculado à obra.',
  texto_fundamentacao_normativa = 'A Anotação de Responsabilidade Técnica (ART) vincula legalmente o profissional habilitado à atividade técnica de projeto, execução e fiscalização, definindo a responsabilidade perante o CREA. A Lei nº 6.496/1977 institui a ART como obrigatória para todo contrato de serviço de engenharia. Aplica-se ainda o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, cujas peças devem ter ART recolhida pelo respectivo autor. O critério "execução, fiscalização e projetos com ART recolhida" integra o plano de inspeção documental e constitui requisito verificável de responsabilidade técnica da obra.',
  texto_risco_consequencia = 'A ausência de ART recolhida para execução, fiscalização ou projeto significa atividade técnica sem responsável legalmente identificado, fragilizando a responsabilização técnica, expondo a obra a autuação pelo CREA e comprometendo a validade formal dos serviços e da garantia legal. Enquanto não regularizada, permanece a lacuna de vínculo técnico. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) relacionar as atividades de projeto, execução e fiscalização e cruzar com as ART recolhidas, identificando as pendentes; (ii) providenciar a emissão e o recolhimento das ART faltantes junto ao CREA pelos profissionais responsáveis; (iii) evidenciar a regularização com as ART recolhidas arquivadas e registro do comprovante/protocolo ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver acidente de trabalho não comunicado por ausência de envio do S-2210 no prazo legal, ou omissão continuada dos eventos de SST.',
  texto_fundamentacao_normativa = 'Os eventos de Segurança e Saúde no Trabalho do eSocial formalizam obrigações legais: o S-2210 comunica o acidente de trabalho (CAT), o S-2220 registra o monitoramento da saúde do trabalhador (vinculado ao ASO) e o S-2240 informa as condições ambientais e os agentes nocivos a que o trabalhador está exposto. O eSocial, instituído no âmbito do Decreto nº 8.373/2014, torna esses envios obrigatórios, em articulação com o PCMSO (NR-07) e o PGR (NR-01). O critério "eventos S-2210/2220/2240 sendo enviados" integra o plano de inspeção documental e constitui requisito verificável de conformidade legal e previdenciária.',
  texto_risco_consequencia = 'O atraso ou a omissão dos eventos de SST no eSocial configura descumprimento de obrigação legal, sujeitando a empresa a multas e, no caso do S-2210, à não comunicação tempestiva do acidente de trabalho, com prejuízo à proteção previdenciária do empregado e agravamento da responsabilização. Enquanto pendente, mantém-se a inconsistência das informações de SST. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) auditar o status de transmissão dos eventos S-2210, S-2220 e S-2240 e identificar envios pendentes, rejeitados ou fora do prazo; (ii) regularizar as transmissões junto à contabilidade/SST e implantar rotina de controle de prazos; (iii) evidenciar a regularização com os protocolos de recibo dos eventos e registro do relatório de conformidade do eSocial ({{evidencia_foto_correcao}}), submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'DC-01' and item_numero = 11;

-- EM-01 (11 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a obra operar sem plano de emergência algum ou se os cenários de risco relevantes (incêndio, soterramento, queda de altura, choque) não estiverem contemplados.',
  texto_fundamentacao_normativa = 'O plano de resposta a emergências deve estar disponível no canteiro, atualizado e ajustado aos cenários específicos da obra, decorrendo do gerenciamento de riscos ocupacionais previsto na NR-01 (PGR) e das exigências de segurança da NR-18 aplicáveis à indústria da construção. A ABNT NBR 15219 (plano de emergência contra incêndio) estabelece a estrutura de conteúdo, os cenários e as responsabilidades esperadas. O critério "atualizado, com cenários da obra" integra o plano de inspeção e constitui requisito verificável de aceitação, pois um plano genérico ou defasado não reflete os riscos reais da frente de serviço.',
  texto_risco_consequencia = 'A ausência ou desatualização do plano de emergência retira da equipe a referência de como agir diante de acidente grave, incêndio ou evacuação, aumentando o tempo de resposta, a improvisação e a gravidade das consequências à vida e ao patrimônio. A permanência da condição mantém a obra sem estrutura formal de resposta até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar ou revisar o plano de emergência contemplando os cenários efetivos da obra (incêndio, acidente pessoal, soterramento, condições climáticas adversas) e as responsabilidades definidas; (ii) disponibilizar o documento atualizado no canteiro e divulgá-lo à equipe em DDS/treinamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do plano afixado e da lista de presença da divulgação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se não houver brigadista algum em turno de trabalho ou se o efetivo treinado for insuficiente para os cenários e o layout da obra.',
  texto_fundamentacao_normativa = 'A obra deve dispor de brigada de emergência formada, com brigadistas treinados e identificados, capaz de atuar na primeira resposta a incêndios e acidentes. A ABNT NBR 14276 (brigada de incêndio — requisitos) define composição, treinamento e identificação dos brigadistas, e a NR-18 estabelece a organização da segurança no canteiro. O critério "brigadistas treinados e identificados" integra o plano de inspeção e constitui requisito verificável, pois uma brigada apenas nominal, sem treinamento vigente ou sem identificação, não assegura resposta efetiva.',
  texto_risco_consequencia = 'A inexistência de brigada treinada e identificada compromete a primeira resposta em sinistro, atrasando o combate a princípio de incêndio e o socorro à vítima, o que pode transformar ocorrências controláveis em acidentes graves ou fatais. A permanência da condição mantém a frente de serviço sem capacidade organizada de intervenção imediata. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) constituir formalmente a brigada, dimensionando o número de brigadistas por turno conforme o efetivo e o layout da obra; (ii) capacitar os brigadistas em combate a incêndio, evacuação e primeiros socorros, e identificá-los (crachá, colete ou braçadeira); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos brigadistas identificados e dos certificados de treinamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se nenhum simulado houver sido realizado no período previsto ou se as lições aprendidas de simulado anterior não tiverem sido tratadas.',
  texto_fundamentacao_normativa = 'A realização periódica de simulado de emergência, com registro, avaliação e lições aprendidas, é o mecanismo que valida na prática o plano de resposta e o preparo da brigada. A ABNT NBR 15219 prevê os exercícios simulados como parte do ciclo de melhoria do plano de emergência, e a NR-01 sustenta o tratamento das oportunidades de melhoria identificadas. O critério "registro com avaliação e lições aprendidas" integra o plano de inspeção e constitui requisito verificável, pois um simulado sem avaliação documentada não gera aprendizado nem correção das falhas observadas.',
  texto_risco_consequencia = 'A ausência de simulado no período impede testar o plano e o tempo de evacuação em condição controlada, de modo que falhas de rota, comunicação ou acionamento só serão descobertas durante uma emergência real, quando o custo do erro é a integridade das pessoas. A permanência da condição mantém o plano não validado e a equipe sem prática de resposta. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) programar e executar simulado aderente a um cenário crítico da obra (evacuação por incêndio ou resgate de vítima), com cronometragem e observadores; (ii) registrar a avaliação, consolidar as lições aprendidas e definir plano de ação para as falhas detectadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do simulado e do relatório de avaliação assinado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver extintor descarregado, despressurizado, vencido ou obstruído em área de risco de incêndio ou próximo a inflamáveis.',
  texto_fundamentacao_normativa = 'Os extintores devem estar com lacre íntegro, carga e pressão adequadas, acesso livre e inspeção mensal registrada, garantindo prontidão de uso. Aplicam-se a NR-23 (proteção contra incêndios) e as ABNT NBR 12693 (sistemas de proteção por extintores) e NBR 12962 (inspeção, manutenção e recarga de extintores), que definem a instalação, a sinalização e o controle periódico. O critério "lacre, carga, pressão, acesso livre, inspeção mensal registrada" integra o plano de inspeção e constitui requisito verificável, pois um extintor obstruído ou sem carga é equipamento indisponível no momento crítico.',
  texto_risco_consequencia = 'Extintor sem carga, despressurizado ou de acesso obstruído falha justamente no princípio de incêndio, permitindo que o fogo evolua e atinja materiais, estruturas provisórias e pessoas antes da chegada de recursos externos. A permanência da condição mantém a proteção contra incêndio comprometida em toda a área coberta pelo equipamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) substituir ou recarregar de imediato os extintores com lacre rompido, carga vencida ou pressão fora da faixa; (ii) desobstruir e sinalizar os pontos de instalação, restabelecendo o acesso livre, e regularizar o registro da inspeção mensal na ficha/etiqueta; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos extintores regularizados e do controle de inspeção atualizado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o sistema de hidrantes ou a reserva técnica de incêndio existente estiver inoperante em edificação/canteiro que dele dependa como proteção principal.',
  texto_fundamentacao_normativa = 'Quando existentes, o sistema de hidrantes e a reserva de incêndio devem estar funcionais, com pressão, vazão e componentes (mangueiras, esguichos, registros) em condição de uso. Aplica-se a ABNT NBR 13714 (sistemas de hidrantes e mangotinhos para combate a incêndio), que define os requisitos de projeto e de operação, em conjunto com a NR-23. O critério "quando existentes, funcionais" integra o plano de inspeção e constitui requisito verificável, pois um sistema instalado porém inoperante gera falsa sensação de proteção sem oferecer defesa real.',
  texto_risco_consequencia = 'Hidrante ou reserva de incêndio inoperante retira a capacidade de combate a incêndio de maior porte, quando os extintores portáteis já não são suficientes, permitindo a propagação do fogo com risco à vida e perda total do patrimônio protegido. A permanência da condição mantém a edificação ou o canteiro sem seu recurso principal de combate. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar o sistema verificando nível da reserva, pressão, vazão, integridade de mangueiras, esguichos e registros; (ii) reparar ou substituir os componentes com defeito e restabelecer o abastecimento da reserva técnica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do sistema testado e do relatório de teste hidrostático/funcional, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se maca ou imobilizadores estiverem ausentes, danificados ou inservíveis, comprometendo o resgate de vítima com suspeita de trauma.',
  texto_fundamentacao_normativa = 'A obra deve dispor de maca e imobilizadores (colar cervical, prancha, talas) disponíveis e em bom estado, para acondicionar e transportar com segurança vítima de trauma até o atendimento definitivo. O requisito decorre da estrutura de primeiros socorros exigida no ambiente de trabalho pela NR-07 e das obrigações de segurança da NR-18, complementadas pelas boas práticas de resgate. O critério "disponíveis e em bom estado" integra o plano de inspeção e constitui requisito verificável, pois equipamento avariado ou indisponível inviabiliza a imobilização adequada no momento do socorro.',
  texto_risco_consequencia = 'A falta de maca e imobilizadores em condição de uso obriga a movimentação improvisada da vítima, o que pode agravar lesões de coluna e fraturas, converter lesões reversíveis em sequelas permanentes e comprometer o transporte seguro até o socorro. A permanência da condição mantém a obra sem meios adequados para o resgate de acidentados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) prover ou substituir maca e o conjunto de imobilizadores, verificando integridade de tirantes, fivelas e superfícies; (ii) definir local de guarda sinalizado e de acesso rápido, com responsável pela conferência periódica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos equipamentos disponíveis e em bom estado no ponto de guarda, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se o kit estiver ausente, incompleto para o efetivo da obra ou com itens essenciais vencidos.',
  texto_fundamentacao_normativa = 'O material de primeiros socorros deve estar completo, guardado em local adequado e com itens dentro da validade, sob responsabilidade de pessoa treinada para seu uso. A obrigatoriedade de material de primeiros socorros no ambiente de trabalho decorre da NR-07 e da estrutura de atendimento prevista na NR-18. O critério "itens dentro da validade" integra o plano de inspeção e constitui requisito verificável, pois insumo vencido ou faltante compromete a eficácia e a segurança do primeiro atendimento.',
  texto_risco_consequencia = 'Kit de primeiros socorros incompleto ou com material vencido atrasa e degrada o atendimento inicial de ferimentos, queimaduras e hemorragias, aumentando o risco de infecção e de agravamento até a chegada do socorro especializado. A permanência da condição mantém a frente de trabalho sem capacidade confiável de primeiro atendimento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inventariar o kit conferindo itens e respectivas validades frente a uma lista de referência; (ii) repor os insumos faltantes e substituir os vencidos, definindo rotina de conferência periódica com responsável designado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do kit completo e da ficha de controle de validades, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se não houver lista de contatos afixada ou se os números de SAMU, bombeiros e hospital de referência estiverem incorretos/desatualizados.',
  texto_fundamentacao_normativa = 'A lista de contatos de emergência (SAMU, bombeiros, hospital de referência, responsáveis internos) deve estar afixada em ponto visível e mantida atualizada, permitindo o acionamento imediato do socorro externo. O requisito compõe o plano de atendimento a emergências, alinhado à estrutura da ABNT NBR 15219 e às obrigações de organização da segurança da NR-18. O critério "afixada e atualizada" integra o plano de inspeção e constitui requisito verificável, pois um contato desatualizado ou de difícil localização retarda o acionamento no instante decisivo.',
  texto_risco_consequencia = 'A ausência ou desatualização da lista de contatos faz a equipe perder minutos críticos procurando ou tentando números inválidos durante uma emergência, atrasando o socorro e agravando o desfecho de acidentes e sinistros. A permanência da condição mantém incerto o acionamento tempestivo dos recursos externos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar e conferir a lista de contatos de emergência, validando os números junto aos serviços locais (SAMU, corpo de bombeiros, hospital de referência); (ii) afixá-la em pontos visíveis do canteiro (portaria, refeitório, frentes de serviço) e definir responsável por sua atualização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da lista afixada e legível, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o contrato/efetivo exigir veículo de emergência dedicado e este estiver ausente, ou se não houver tempo-resposta definido para obra de acesso remoto.',
  texto_fundamentacao_normativa = 'Deve haver ambulância ou veículo de emergência disponível conforme o previsto em contrato e o dimensionado para o efetivo, com tempo-resposta definido para remoção de vítima. O requisito decorre das obrigações de atendimento a emergências e primeiros socorros associadas à NR-18 e à NR-07, e das especificações contratuais da obra. O critério "disponível conforme contrato/efetivo, tempo-resposta definido" integra o plano de inspeção e constitui requisito verificável, pois a mera previsão contratual sem meio efetivamente mobilizado não assegura a remoção da vítima.',
  texto_risco_consequencia = 'A indisponibilidade de veículo de emergência ou a falta de tempo-resposta definido prolonga o intervalo entre o acidente e o atendimento hospitalar, período em que o quadro de vítima grave pode evoluir para sequelas irreversíveis ou óbito, sobretudo em obras de acesso difícil. A permanência da condição mantém a remoção de acidentados sem garantia de prazo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confirmar a disponibilidade do veículo de emergência exigido pelo contrato e adequado ao efetivo, com condutor e equipe definidos; (ii) formalizar o fluxo e o tempo-resposta de remoção até o hospital de referência, incluindo acionamento alternativo (SAMU/convênio) quando o recurso próprio não for previsto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do veículo/contrato e do procedimento de remoção divulgado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se não houver ponto de encontro definido/sinalizado ou se a equipe desconhecer sua localização em obra com risco de evacuação.',
  texto_fundamentacao_normativa = 'O ponto de encontro para evacuação deve estar definido em local seguro, devidamente sinalizado e conhecido por todos os trabalhadores, permitindo a conferência de efetivo após a saída da área de risco. O requisito integra o plano de emergência e a rota de fuga, alinhado à estrutura da ABNT NBR 15219 e às obrigações de sinalização e organização da NR-18. O critério "conhecido por todos" integra o plano de inspeção e constitui requisito verificável, pois um ponto de encontro não sinalizado ou ignorado pela equipe não cumpre sua função durante a evacuação.',
  texto_risco_consequencia = 'A ausência de ponto de encontro sinalizado e conhecido dispersa os trabalhadores durante a evacuação e impede a conferência do efetivo, dificultando identificar quem permaneceu na área de risco e direcionar as equipes de resgate. A permanência da condição mantém a evacuação sem ponto de controle confiável. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) definir o ponto de encontro em local seguro, afastado das áreas de risco e das rotas de acesso dos socorristas; (ii) sinalizá-lo de forma padronizada e divulgá-lo à equipe em DDS e nas rotas de fuga; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da sinalização instalada e da divulgação realizada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se a rota até o hospital de referência não estiver mapeada, ou a Crítica em obra de acesso remoto sem rota testada e alternativa definida.',
  texto_fundamentacao_normativa = 'A rota de remoção até o hospital de referência deve estar mapeada e testada, com trajeto, distância e tempo estimado conhecidos, integrando o fluxo de resposta a emergências da obra. O requisito compõe o plano de atendimento a emergências, alinhado à estrutura da ABNT NBR 15219 e às boas práticas de logística de socorro, sem norma numérica específica que discipline o traçado em obra. O critério "mapeada e testada" integra o plano de inspeção e constitui requisito verificável, pois uma rota apenas presumida pode conter impedimentos (obras, bloqueios, distância real) só percebidos durante a emergência.',
  texto_risco_consequencia = 'Rota de remoção não mapeada ou não testada expõe o transporte da vítima a atrasos por trajeto inadequado, bloqueios ou escolha de hospital sem recurso para o caso, prolongando o tempo até o atendimento definitivo e agravando o desfecho clínico. A permanência da condição mantém incerta a logística de socorro da obra. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear a rota principal até o hospital de referência, registrando trajeto, distância e tempo estimado, e definir rota alternativa; (ii) percorrer/testar o trajeto para confirmar viabilidade e a capacidade de atendimento do hospital, divulgando o fluxo à equipe; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do mapa de rota afixado e do registro do teste realizado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EM-01' and item_numero = 11;

-- EQ-01 (11 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de verificação pré-uso incidir sobre máquina com dispositivos de segurança comprometidos ou empregada em operação de risco elevado (içamento, movimentação de cargas, elevação de pessoas).',
  texto_fundamentacao_normativa = 'A verificação diária pré-uso, formalizada em checklist assinado pelo operador antes do início do turno, constitui barreira preventiva contra a operação de máquina com defeito latente. Aplica-se a NR-12 (Segurança no Trabalho em Máquinas e Equipamentos), que atribui ao operador a verificação das condições de segurança antes do uso, complementada pelo manual do fabricante e pelas boas práticas de gestão de SSMA da obra. O critério "Preenchido pelo operador antes do turno" integra o plano de inspeção da obra e constitui requisito verificável de liberação do equipamento.',
  texto_risco_consequencia = 'A operação de máquina sem verificação prévia permite que falhas incipientes — em freios, comandos ou proteções — evoluam para pane ou acidente durante o turno, expondo o operador e terceiros a lesões e paralisando a frente de serviço. A permanência da condição mantém o equipamento liberado sem barreira documental de controle. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar ou retomar o preenchimento do checklist diário pré-uso pelo operador antes do início do turno, com bloqueio de partida diante de pendência em itens críticos; (ii) capacitar o operador quanto ao preenchimento e à identificação de não conformidades; (iii) arquivar os checklists e evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a falta de lubrificação atingir componentes críticos de segurança (freios, sistema de direção, articulações de lança) ou já apresentar sinais de desgaste anormal ou ruído.',
  texto_fundamentacao_normativa = 'A lubrificação nos intervalos e com os insumos definidos pelo fabricante preserva a integridade de mancais, engrenagens e articulações, prevenindo desgaste prematuro e travamento. A exigência decorre do manual do fabricante e do plano de manutenção da obra, que estabelecem o cronograma de lubrificação por horímetro e calendário; não se invoca número de norma específico por se tratar de requisito de manutenção definido pelo fabricante. O critério "Plano de lubrificação seguido" integra o plano de inspeção da obra e constitui requisito verificável de conservação do equipamento.',
  texto_risco_consequencia = 'A ausência de lubrificação nos pontos e prazos previstos acelera o desgaste de componentes móveis, elevando o risco de travamento, superaquecimento e falha mecânica em serviço, com parada não programada e custo de reparo majorado. A permanência da condição mantém o componente sujeito a atrito inadequado até a regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar a lubrificação pendente nos pontos e com os insumos especificados no manual do fabricante; (ii) atualizar o plano de lubrificação e vinculá-lo ao horímetro, definindo os próximos vencimentos; (iii) evidenciar a execução com registro fotográfico ({{evidencia_foto_correcao}}) e anotação na ficha do equipamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o vazamento for de combustível, atingir superfície aquecida ou corpo hídrico/solo, ou comprometer o sistema hidráulico responsável por funções de segurança.',
  texto_fundamentacao_normativa = 'A estanqueidade dos sistemas hidráulico, de lubrificação e de combustível é condição de operação segura e de proteção ambiental, evitando perda de pressão em funções críticas e contaminação do solo. Aplica-se a NR-12 (Segurança no Trabalho em Máquinas e Equipamentos), quanto à integridade dos sistemas do equipamento, complementada pelas boas práticas de gestão ambiental e de prevenção de incêndio da obra. O critério "Hidráulico, óleo, combustível" delimita os sistemas a inspecionar e integra o plano de inspeção da obra como requisito verificável.',
  texto_risco_consequencia = 'Vazamento em sistema hidráulico pode provocar perda súbita de pressão e queda de carga ou de implemento; vazamento de óleo ou combustível gera risco de incêndio e de contaminação de solo e águas, com passivo ambiental e sanções. A permanência da condição mantém ativo o foco de vazamento e o risco associado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar a origem do vazamento e substituir mangueiras, vedações ou conexões danificadas; (ii) conter e remover o resíduo derramado com kit de mitigação, destinando-o adequadamente; (iii) evidenciar o reparo e a limpeza com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando faltar ART de içamento ou laudo técnico de equipamento envolvido em movimentação de cargas ou elevação de pessoas.',
  texto_fundamentacao_normativa = 'A guarda da documentação — manual de operação, laudos técnicos e Anotação de Responsabilidade Técnica (ART) de içamento quando aplicável — assegura a rastreabilidade da conformidade técnica e da responsabilização profissional do equipamento. Aplicam-se a NR-12, que exige a disponibilização do manual em língua portuguesa, a NR-11 (Transporte, Movimentação, Armazenagem e Manuseio de Materiais) quanto às operações de içamento, e a ART prevista na Lei nº 6.496/1977 para os serviços sob responsabilidade de profissional habilitado. O critério "Manual, laudos, ART de içamento quando aplicável" integra o plano de inspeção da obra como requisito documental verificável.',
  texto_risco_consequencia = 'A ausência de documentação impede comprovar a aptidão técnica do equipamento e a responsabilidade profissional pelas operações de içamento, expondo a obra a embargo, à interdição do equipamento e à responsabilização em caso de acidente. A permanência da condição mantém o equipamento operando sem lastro documental. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reunir e arquivar no canteiro o manual, os laudos vigentes e a ART de içamento assinada por profissional habilitado, quando aplicável; (ii) vincular a documentação à ficha do equipamento e verificar as validades; (iii) evidenciar a regularização com registro fotográfico e digitalização dos documentos ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a manutenção vencida incidir sobre sistemas de segurança (freios, direção, dispositivos de proteção) ou quando o horímetro exceder significativamente o intervalo previsto.',
  texto_fundamentacao_normativa = 'A execução da manutenção preventiva conforme o plano, aferida pelo horímetro, mantém o equipamento dentro das condições de projeto e prevê a substituição de itens de desgaste antes da falha. A exigência decorre do manual do fabricante e do plano de manutenção da obra e é reforçada pela NR-12, que determina a manutenção segundo as especificações do fabricante. O critério "Plano × horímetro" integra o plano de inspeção da obra e constitui requisito verificável de conservação.',
  texto_risco_consequencia = 'Manutenção preventiva em atraso eleva a probabilidade de falha em serviço, reduz a vida útil dos componentes e pode comprometer sistemas de segurança, com risco de acidente e parada não programada da frente. A permanência da condição mantém o equipamento operando fora da janela de manutenção prevista. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar as intervenções preventivas vencidas conforme o plano e o horímetro atual; (ii) reprogramar os próximos vencimentos e registrá-los na ficha do equipamento; (iii) evidenciar a execução com registro fotográfico e ordem de serviço ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Observação — elevar a Menor quando a ausência de registro do horímetro comprometer o controle da manutenção preventiva ou a apropriação de horas para faturamento e medição.',
  texto_fundamentacao_normativa = 'O registro sistemático do horímetro é a base de dados que sustenta a programação da manutenção preventiva e o controle de horas trabalhadas e paradas do equipamento. A exigência decorre do plano de manutenção e dos controles de gestão da obra; não se invoca número de norma específico por se tratar de controle gerencial do ativo. O critério "Controle de horas trabalhadas/paradas" integra o plano de inspeção da obra como requisito verificável de gestão.',
  texto_risco_consequencia = 'Sem registro confiável do horímetro, a manutenção preventiva perde a referência de acionamento e as horas de operação e parada deixam de ser apropriadas, prejudicando a gestão de custos e a rastreabilidade do uso. A permanência da condição mantém o equipamento sem base de controle horária. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retomar o registro diário do horímetro em planilha ou ficha do equipamento; (ii) conciliar a leitura atual com os últimos registros e vinculá-la ao plano de manutenção; (iii) evidenciar a regularização com registro fotográfico do horímetro e da planilha ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em frentes com circulação de pessoas a pé, tráfego conjunto de máquinas ou condições de baixa visibilidade.',
  texto_fundamentacao_normativa = 'A sinalização sonora e o alarme de marcha à ré funcionais alertam pedestres e demais operadores sobre o deslocamento da máquina móvel, prevenindo atropelamentos em pontos cegos. Aplicam-se a NR-18 (Segurança e Saúde no Trabalho na Indústria da Construção), quanto à sinalização de advertência das máquinas móveis, e a NR-12 quanto aos dispositivos de segurança do equipamento. O critério "Funcionais em máquinas móveis" integra o plano de inspeção da obra e constitui requisito verificável de liberação da máquina.',
  texto_risco_consequencia = 'Alarme de ré inoperante suprime o aviso de deslocamento em marcha à ré, elevando o risco de atropelamento de trabalhadores a pé, sobretudo em pontos cegos e áreas de tráfego conjunto, com potencial de lesão grave ou fatal. A permanência da condição mantém a máquina circulando sem alerta acústico. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reparar ou substituir o alarme sonoro de ré e a sinalização luminosa, restabelecendo o acionamento automático na marcha à ré; (ii) testar o dispositivo e registrá-lo no checklist pré-uso; (iii) evidenciar o reparo e o teste com registro fotográfico ou vídeo ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o extintor estiver ausente, descarregado ou vencido em equipamento que opere próximo a materiais inflamáveis ou a pontos de abastecimento.',
  texto_fundamentacao_normativa = 'O extintor embarcado, com carga válida e devidamente fixado, é o meio de primeiro combate a princípio de incêndio na própria máquina, integrando o plano de emergência da obra. Verificam-se a validade da carga e a firmeza da fixação segundo as boas práticas de proteção contra incêndio e o plano de emergência do canteiro; não se cita número de norma específico por não haver certeza de sua aplicação a extintor embarcado em máquina. O critério "Carga válida e fixado" integra o plano de inspeção da obra como requisito verificável de segurança.',
  texto_risco_consequencia = 'Extintor vencido, descarregado ou mal fixado inviabiliza o combate imediato a princípio de incêndio na máquina e pode transformar-se em projétil em caso de tombamento ou frenagem brusca, agravando o cenário de emergência. A permanência da condição mantém a máquina sem meio de combate confiável. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) substituir ou recarregar o extintor, assegurando carga dentro da validade e agente compatível com a classe de risco; (ii) fixá-lo em suporte próprio, de acesso rápido e protegido de intempéries; (iii) evidenciar a regularização com registro fotográfico do extintor, do selo de validade e da fixação ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em máquinas sujeitas a tombamento ou que operem em taludes, rampas ou terreno acidentado.',
  texto_fundamentacao_normativa = 'O uso do cinto de segurança do assento mantém o operador dentro da estrutura de proteção contra tombamento (ROPS) da máquina móvel, sendo condição para a eficácia dessa proteção. Aplica-se a NR-12 quanto ao uso dos dispositivos de segurança do posto de operação, complementada pelo manual do fabricante e pelas boas práticas de SSMA; não se invoca outra norma por não haver certeza de aplicação específica. O critério "Operadores de máquinas móveis" delimita o alcance e integra o plano de inspeção da obra como requisito verificável.',
  texto_risco_consequencia = 'Sem o cinto afivelado, em caso de tombamento o operador pode ser projetado para fora da cabine e esmagado pela própria estrutura, anulando a proteção da ROPS, com risco de lesão grave ou fatal. A permanência da condição mantém o operador desprotegido durante toda a operação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) exigir e fiscalizar o uso do cinto de segurança pelo operador durante toda a operação; (ii) inspecionar a integridade do cinto e do afivelamento, substituindo-o se danificado; (iii) reforçar a orientação em diálogo de segurança e evidenciar a conformidade com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando houver trabalho noturno programado, operação em ambiente confinado ou túnel, ou tráfego conjunto com pessoas e veículos.',
  texto_fundamentacao_normativa = 'A iluminação e os faróis funcionais garantem visibilidade adequada ao operador e a sinalização da máquina para terceiros durante o trabalho noturno ou em baixa luminosidade. Aplica-se a NR-18 quanto à iluminação adequada das frentes de trabalho, complementada pelo manual do fabricante e pelas boas práticas de SSMA. O critério "Funcionais para trabalho noturno" integra o plano de inspeção da obra e constitui requisito verificável de liberação para operação em baixa luminosidade.',
  texto_risco_consequencia = 'Faróis e iluminação inoperantes reduzem a visibilidade do operador e a percepção da máquina por terceiros no período noturno, elevando o risco de colisão, atropelamento e erro operacional. A permanência da condição mantém a máquina sem visibilidade adequada para operação noturna. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reparar ou substituir faróis e o sistema de iluminação, verificando fiação e fusíveis; (ii) testar o conjunto nas condições de trabalho noturno e registrá-lo no checklist pré-uso; (iii) evidenciar o reparo e o teste com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver dano à isolação (cabo descascado, carcaça trincada, plugue rompido) com exposição de partes energizadas ou uso em ambiente úmido.',
  texto_fundamentacao_normativa = 'A integridade de carcaça, cabo e plugue das ferramentas elétricas preserva o isolamento contra o contato acidental com partes energizadas, prevenindo choque elétrico. Aplicam-se a NR-10 (Segurança em Instalações e Serviços em Eletricidade), quanto à segurança de equipamentos e ferramentas elétricas, e a NR-12 quanto à integridade das ferramentas; o exame visual de carcaça, cabo e plugue é a verificação prevista. O critério "Carcaça, cabo e plugue sem danos" integra o plano de inspeção da obra como requisito verificável de aceitação da ferramenta.',
  texto_risco_consequencia = 'Ferramenta elétrica com cabo descascado, plugue rompido ou carcaça trincada expõe o operador a choque elétrico e curto-circuito, com risco de queimadura, parada cardiorrespiratória e princípio de incêndio. A permanência da condição mantém a ferramenta energizável em estado inseguro. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de uso e etiquetar a ferramenta danificada, impedindo sua utilização; (ii) reparar por profissional habilitado ou substituir cabo, plugue e carcaça, verificando a continuidade do aterramento ou a dupla isolação; (iii) evidenciar o reparo ou a substituição com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EQ-01' and item_numero = 11;

-- MA-01 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — rebaixar a Menor quando a mistura for pontual, restrita a resíduos Classe II e prontamente reversível; elevar a Crítica se houver mistura de resíduo perigoso (Classe I) com resíduo comum, contaminando o lote',
  texto_fundamentacao_normativa = 'A segregação na origem é a base do gerenciamento de resíduos e condiciona a triagem, a valorização e a destinação ambientalmente adequada de cada fração. Aplicam-se a Política Nacional de Resíduos Sólidos (Lei nº 12.305/2010), a Resolução CONAMA nº 275/2001, que estabelece o código de cores para a coleta seletiva, e a NBR 10004, que classifica os resíduos sólidos quanto à periculosidade. O critério "Coleta seletiva implantada (cores CONAMA)" integra o Plano de Gerenciamento de Resíduos da Construção Civil da obra e constitui requisito verificável de aceitação da gestão ambiental do canteiro.',
  texto_risco_consequencia = 'A ausência de separação por classe inviabiliza a reciclagem, aumenta o volume encaminhado a aterro e, sobretudo, cria contaminação cruzada quando frações perigosas se misturam a resíduos comuns, elevando o passivo ambiental, o custo de destinação e a exposição a autuações dos órgãos ambientais. Enquanto não corrigida, a condição perpetua a geração de lotes misturados sem rastreabilidade de classe. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar ou recompor os pontos de coleta seletiva, disponibilizando coletores nas cores CONAMA correspondentes a cada classe gerada na obra; (ii) capacitar as equipes de produção e de limpeza quanto à separação na origem e ao descarte por tipo de resíduo; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos pontos regularizados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a falta de identificação recair sobre baia de resíduo perigoso (Classe I) ou provocar descarte sistematicamente incorreto pelas equipes',
  texto_fundamentacao_normativa = 'A identificação de coletores e baias é o instrumento que torna a segregação executável em campo, orientando o gerador quanto ao resíduo admitido em cada recipiente. Fundamenta-se na Resolução CONAMA nº 275/2001 (código de cores), na classificação da NBR 10004 e no layout de canteiro/plano de resíduos aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define a localização e a destinação das baias. O critério "Placas por tipo de resíduo" é requisito verificável de sinalização e integra o plano de inspeção ambiental da obra.',
  texto_risco_consequencia = 'Baias e coletores sem placas por tipo de resíduo induzem descarte incorreto, misturam frações que deveriam ser segregadas e comprometem toda a cadeia posterior de triagem, transporte e destinação, gerando retrabalho de separação e risco de reclassificação do lote como perigoso. A permanência da lacuna mantém a sinalização deficiente como fonte contínua de erro de segregação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar placas de identificação em cada coletor e baia, indicando o tipo de resíduo, a classe e a cor CONAMA correspondente; (ii) posicionar a sinalização de forma visível e durável, compatível com o layout aprovado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das baias identificadas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica havendo vazamento ativo de resíduo perigoso, tambor sem tampa exposto à chuva ou risco de derramamento em solo/drenagem; rebaixar a Menor se restrito à mera ausência de rótulo em recipiente íntegro e estanque',
  texto_fundamentacao_normativa = 'A integridade, o fechamento e a identificação de bombonas e tambores garantem a contenção do resíduo e a estanqueidade do armazenamento temporário, especialmente para frações líquidas e perigosas. Aplicam-se a NBR 12235, que trata do armazenamento de resíduos sólidos perigosos (Classe I), e a NBR 10004, quanto à classificação. O critério "Sem vazamentos, tampados, identificados" constitui requisito verificável de aceitação da guarda temporária e integra o plano de inspeção ambiental do canteiro.',
  texto_risco_consequencia = 'Recipientes furados, sem tampa ou não identificados permitem vazamento e volatilização do conteúdo, contaminando solo, água pluvial e trabalhadores, além de impedir a rastreabilidade da fração armazenada; o contato de resíduo perigoso com o meio pode gerar passivo ambiental de difícil remediação e responsabilização legal. Enquanto os recipientes permanecerem comprometidos, mantém-se ativo o potencial de derramamento e contaminação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) substituir ou remanejar imediatamente as bombonas e tambores danificados para recipientes íntegros e compatíveis com o resíduo; (ii) manter todos os recipientes tampados e rotulados com o tipo, a classe e a periculosidade do conteúdo, recolhendo eventual produto derramado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos recipientes regularizados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica sempre que a central de perigosos operar sem impermeabilização, cobertura ou contenção; rebaixar a Maior apenas se um único desses elementos estiver em implantação e não houver resíduo perigoso já estocado no local',
  texto_fundamentacao_normativa = 'A área de armazenamento de resíduos perigosos (Classe I) exige piso impermeável, cobertura e bacia de contenção para impedir a percolação de líquidos e o contato com águas pluviais. Aplicam-se a NBR 12235 (armazenamento de resíduos sólidos perigosos), a NBR 10004 (classificação como Classe I) e o layout de canteiro aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixa a locação e as características construtivas da central de resíduos. O critério "Piso impermeável, cobertura, contenção" é requisito verificável de aceitação e integra o plano de inspeção ambiental da obra.',
  texto_risco_consequencia = 'A guarda de resíduos Classe I em área sem impermeabilização, cobertura e contenção permite a infiltração de contaminantes no solo e o carreamento pela chuva para a drenagem e o lençol freático, configurando dano ambiental grave, com risco de embargo, multa e obrigação de remediação. Enquanto a central não atender aos três requisitos, cada evento de chuva ou derramamento amplia a extensão da contaminação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar ou complementar a impermeabilização do piso, a cobertura e a bacia de contenção da central de perigosos, conforme layout aprovado; (ii) até a conclusão, isolar a área e transferir os resíduos Classe I para guarda provisória estanque e coberta; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da central regularizada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a destinação sem MTR envolver resíduo perigoso (Classe I) ou transportador/destino não licenciado; rebaixar a Menor se o documento existir e a pendência for apenas de registro/arquivamento formal',
  texto_fundamentacao_normativa = 'O Manifesto de Transporte de Resíduos (MTR) é o documento que assegura a rastreabilidade da carga desde a geração até a destinação final, vinculando gerador, transportador e destinatário. Fundamenta-se na Política Nacional de Resíduos Sólidos (Lei nº 12.305/2010), no Sistema Nacional de Informações sobre a Gestão dos Resíduos Sólidos (SINIR/MTR) e na NBR 13221, que trata do transporte terrestre de resíduos. O critério "Emitido para toda destinação" é requisito verificável de conformidade documental e integra o plano de inspeção ambiental da obra.',
  texto_risco_consequencia = 'Destinar resíduos sem MTR emitido rompe a cadeia de rastreabilidade, impede a comprovação da destinação ambientalmente adequada e expõe o gerador à responsabilização solidária por eventual descarte irregular pelo transportador, além de sujeitar a obra a autuação por descumprimento da legislação de resíduos. Enquanto houver cargas sem manifesto, a obra permanece sem prova de destinação regular dos volumes já expedidos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) emitir e regularizar o MTR de cada movimentação de resíduo, vinculando gerador, transportador e destinatário licenciados; (ii) implantar rotina que condicione a saída de qualquer carga à prévia emissão do manifesto correspondente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e cópia dos manifestos emitidos, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando não houver comprovação de que o destino é licenciado ou quando envolver resíduo perigoso sem CDF; rebaixar a Menor se a destinação for comprovadamente licenciada e faltar apenas o arquivamento do comprovante',
  texto_fundamentacao_normativa = 'A destinação final deve ocorrer exclusivamente em unidade devidamente licenciada, comprovada por Certificado de Destinação Final (CDF) e comprovantes arquivados que encerram o ciclo de rastreabilidade da carga. Aplicam-se a Política Nacional de Resíduos Sólidos (Lei nº 12.305/2010), que impõe a destinação ambientalmente adequada, e a Resolução CONAMA nº 237/1997, relativa ao licenciamento ambiental das atividades receptoras. O critério "CDF/comprovantes arquivados" é requisito verificável de aceitação e integra o plano de inspeção ambiental da obra.',
  texto_risco_consequencia = 'Encaminhar resíduos a destino não licenciado, ou sem guardar o CDF e os comprovantes, impede demonstrar a destinação adequada e mantém o gerador responsável por eventual disposição irregular, com risco de multa, embargo e dano de imagem; a ausência de arquivo documental fragiliza a defesa da obra em fiscalizações e auditorias. Enquanto os comprovantes não forem obtidos e arquivados, a destinação dos lotes já expedidos permanece sem lastro legal. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confirmar a validade das licenças ambientais das unidades de destinação utilizadas; (ii) obter e arquivar os Certificados de Destinação Final e demais comprovantes de todas as cargas, vinculando-os aos respectivos manifestos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do arquivo documental organizado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a desatualização do inventário impedir conciliar volumes gerados e destinados ou mascarar destinação pendente de resíduo perigoso',
  texto_fundamentacao_normativa = 'O inventário atualizado é o instrumento de controle que consolida volumes gerados, armazenados e destinados por classe, permitindo a conciliação da massa e a demonstração da gestão de resíduos da obra. Fundamenta-se na Política Nacional de Resíduos Sólidos (Lei nº 12.305/2010), que exige o Plano de Gerenciamento de Resíduos Sólidos e o registro sistemático das operações, servindo de base ao acompanhamento gerencial e às prestações de contas ambientais. O critério "Controle de volumes gerados/destinados" é requisito verificável e integra o plano de inspeção ambiental da obra.',
  texto_risco_consequencia = 'Um inventário desatualizado impede identificar acúmulos indevidos, destinar tempestivamente cada fração e comprovar o balanço entre resíduo gerado e resíduo destinado, abrindo espaço para estoques além do prazo, perda de rastreabilidade e inconsistências em auditorias e relatórios aos órgãos ambientais. Enquanto o controle não for regularizado, a obra opera sem visibilidade real dos passivos de resíduos acumulados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) atualizar o inventário com os volumes gerados, armazenados e destinados por classe, conciliando-o com os MTR e os CDF emitidos; (ii) estabelecer rotina periódica de registro e revisão, com responsável designado pela manutenção do controle; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e cópia do inventário atualizado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-01' and item_numero = 7;

-- MA-02 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o derramamento atingir solo exposto, corpo hídrico, rede de drenagem pluvial ou área de recarga, ou quando envolver volume que caracterize incidente ambiental de notificação obrigatória',
  texto_fundamentacao_normativa = 'A ausência de manchas de óleo em solo ou pátios é indicador direto de estanqueidade dos sistemas hidráulicos, de manejo adequado de fluidos e de eficácia da contenção na obra. O controle atende às condicionantes do licenciamento ambiental do empreendimento, ao Plano de Gerenciamento de Resíduos e aos procedimentos de SSMA, que vedam a disposição de óleos e graxas no solo. Não havendo norma técnica específica de numeração certa que este fiscal possa afirmar sem dúvida, a exigência fundamenta-se no critério do item, nas boas práticas de gestão ambiental de canteiro e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, no que dispõe sobre pátios impermeabilizados e drenagem. O critério "Sem manchas em solo ou pátios" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'O derramamento de óleo sobre solo ou pátios contamina a matriz edáfica e pode migrar para águas subterrâneas e para a rede de drenagem pluvial, exigindo remediação, remoção de solo contaminado e eventual notificação ao órgão ambiental, com sobrecusto, passivo ambiental e risco de sanção administrativa; a mancha também caracteriza superfície escorregadia e foco de incêndio. A permanência da condição mantém ativa a fonte de contaminação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) estancar imediatamente a fonte do vazamento e conter o espalhamento com material absorvente, isolando a área afetada; (ii) remover o óleo e o solo/piso impregnado, destinando os resíduos contaminados conforme o Plano de Gerenciamento de Resíduos e acondicionando-os em local identificado; (iii) sanar a causa-raiz (reparo do equipamento, reforço de contenção ou impermeabilização do pátio) e evidenciar a limpeza e a destinação com registro fotográfico ({{evidencia_foto_correcao}}) e comprovantes de destinação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o equipamento estático operar sobre solo exposto ou próximo a drenagem/corpo hídrico sem qualquer contenção, ou quando já houver vestígio de vazamento no ponto',
  texto_fundamentacao_normativa = 'Geradores, compressores e bombas são equipamentos estáticos que armazenam e circulam óleos e combustíveis, com propensão a gotejamento e a pequenos vazamentos em conexões, mangueiras e cárteres; a bandeja de contenção sob o equipamento é barreira de proteção que impede o contato do fluido com o solo. A exigência atende às condicionantes do licenciamento ambiental, aos procedimentos de SSMA e às boas práticas de contenção de canteiro, bem como ao projeto/plano de instalação dos equipamentos. Não havendo, para este ponto, número de norma técnica que este fiscal possa afirmar sem dúvida quanto à existência e à aplicabilidade a este item, a fundamentação apoia-se no critério do item, nas boas práticas de contenção de canteiro e no projeto/plano de instalação aprovado. O critério "Bandejas sob geradores, compressores, bombas" integra o plano de inspeção e constitui requisito verificável de aceitação da instalação do equipamento.',
  texto_risco_consequencia = 'Equipamento estático sem bandeja de contenção transfere qualquer gotejamento ou vazamento diretamente para o solo, gerando contaminação difusa, passivo ambiental e possível migração para a drenagem, além de acúmulo de óleo que caracteriza risco de incêndio e de queda por piso escorregadio. A permanência da condição mantém o solo desprotegido sob o equipamento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar bandeja/bacia de contenção dimensionada para o volume de fluido do equipamento sob cada gerador, compressor e bomba, com material resistente ao produto contido; (ii) verificar e sanar pontos de gotejamento em conexões, mangueiras e vedações, e manter a bandeja limpa e drenada de forma controlada; (iii) evidenciar a contenção instalada e o equipamento sem vazamento com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando a trinca comprometer a estanqueidade da bacia ou o dreno estiver aberto/inoperante; rebaixar a Maior apenas se a falha for superficial, sem perda de contenção, e a bacia mantiver capacidade de retenção',
  texto_fundamentacao_normativa = 'A bacia de contenção é a última barreira de proteção do solo e da água em caso de vazamento de tanques e reservatórios de óleo/combustível, e sua função depende da integridade estrutural (ausência de trincas) e do fechamento dos drenos, para que retenha o volume derramado em vez de conduzi-lo à drenagem. A exigência atende às condicionantes do licenciamento ambiental, aos procedimentos de SSMA e às boas práticas de armazenamento de líquidos e de contenção secundária. Não havendo, para este ponto, número de norma técnica que este fiscal possa afirmar sem dúvida quanto à existência e à aplicabilidade a este item, a fundamentação apoia-se no critério do item, nas boas práticas de contenção e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Sem trincas, drenos fechados" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Bacia trincada ou com dreno aberto perde a capacidade de retenção e, em caso de vazamento, permite a fuga do produto para o solo e para a rede de drenagem pluvial, convertendo um incidente contido em contaminação ambiental de maior extensão, com remediação onerosa, passivo e risco de autuação. A permanência da condição mantém a contenção inoperante e o armazenamento desprotegido até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interditar o uso da bacia comprometida e recuperar sua integridade estrutural, tratando trincas e restabelecendo a estanqueidade e a capacidade de retenção de projeto; (ii) manter os drenos normalmente fechados, operando-os apenas de forma controlada para descarte de água de chuva isenta de óleo, com verificação prévia; (iii) evidenciar a bacia recuperada, íntegra e com drenos fechados por registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando frentes com manuseio ou armazenamento de óleo/combustível ou próximas a corpo hídrico operarem sem kit de emergência ambiental disponível e acessível',
  texto_fundamentacao_normativa = 'O kit de emergência ambiental — absorventes, mantas e cordões de contenção — é o recurso de resposta imediata que permite estancar e conter um derramamento nos primeiros minutos, limitando a área atingida antes que o produto alcance o solo ou a drenagem; sua disponibilidade nas frentes de serviço é condição de eficácia do plano de atendimento a emergências. A exigência atende às condicionantes do licenciamento ambiental, ao Plano de Atendimento a Emergências e aos procedimentos de SSMA da obra, alinhando-se às boas práticas de prontidão ambiental de canteiro. O critério "Absorventes, mantas, cordões disponíveis nas frentes" integra o plano de inspeção e constitui requisito verificável de aceitação da frente de trabalho.',
  texto_risco_consequencia = 'A ausência ou indisponibilidade do kit de emergência nas frentes impede a resposta imediata a um vazamento, permitindo que o produto se espalhe e atinja o solo e a drenagem antes de qualquer contenção, o que amplia a extensão da contaminação, o custo de remediação e a exposição a sanções. A permanência da condição mantém as frentes sem capacidade de resposta a incidentes ambientais até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) disponibilizar kit de emergência ambiental completo e sinalizado em cada frente com risco de derramamento, com absorventes, mantas e cordões em quantidade compatível com o volume manuseado; (ii) verificar periodicamente a integridade e a reposição dos materiais e capacitar a equipe quanto ao uso e ao acionamento do plano de emergência; (iii) evidenciar os kits posicionados e acessíveis nas frentes por registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a troca de óleo ou a manutenção com fluidos ocorrer diretamente sobre solo exposto, sem piso impermeável nem lona, ou nas proximidades de drenagem ou corpo hídrico',
  texto_fundamentacao_normativa = 'As trocas de óleo e as manutenções de máquinas em campo são as operações de maior probabilidade de derramamento, pela abertura de cárteres e conexões e pelo manuseio de fluidos usados; a proteção do local com piso impermeável ou lona interpõe barreira entre a operação e o solo, contendo respingos e vazamentos. A exigência atende às condicionantes do licenciamento ambiental, ao Plano de Gerenciamento de Resíduos e aos procedimentos de SSMA da obra, em linha com as boas práticas de manutenção em campo. O critério "Piso impermeável ou lona nas trocas de óleo em campo" integra o plano de inspeção e constitui requisito verificável de aceitação da atividade de manutenção.',
  texto_risco_consequencia = 'A manutenção com fluidos executada sobre solo desprotegido transfere respingos, óleo usado e borra diretamente para o terreno, gerando contaminação pontual do solo, possível migração para águas e para a drenagem e geração de resíduo perigoso sem contenção, com remediação onerosa, passivo ambiental e risco de sanção. A permanência da condição mantém a atividade de manutenção como fonte de contaminação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) delimitar e proteger a área de manutenção em campo com piso impermeável ou lona resistente sob o ponto de troca, com bandeja de coleta do óleo drenado; (ii) acondicionar o óleo usado, filtros e materiais impregnados em recipientes identificados e destiná-los conforme o Plano de Gerenciamento de Resíduos, mantendo absorventes à mão; (iii) evidenciar a área protegida durante a operação e a destinação dos resíduos por registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-02' and item_numero = 5;

-- MA-03 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o direcionamento inadequado estiver carreando sedimentos para corpo hídrico, via pública ou área de terceiros, ou se houver risco iminente de assoreamento durante evento de chuva.',
  texto_fundamentacao_normativa = 'A drenagem provisória de obra deve conduzir as águas pluviais de forma controlada, com dispositivos dimensionados (valetas, canaletas, descidas d''água e bacias de contenção) que escoem sem velocidade erosiva e sem carrear sólidos para fora da área de intervenção. O requisito decorre do plano de controle ambiental da obra e das condicionantes do licenciamento, complementados pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e por boas práticas de gestão de águas pluviais em canteiro. O critério "Direcionamento sem carrear sedimentos" integra o plano de inspeção e constitui requisito verificável de aceitação, cabendo comprovar o funcionamento efetivo do sistema, inclusive sob chuva.',
  texto_risco_consequencia = 'Drenagem provisória não funcional ou que carreia sedimentos provoca erosão nas superfícies expostas, alagamentos localizados no canteiro e transporte de sólidos para vias, redes públicas e corpos d''água, com potencial de assoreamento, autuação ambiental e paralisação. A permanência da condição mantém ativo o risco de dano ambiental a cada precipitação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revisar o traçado e o dimensionamento dos dispositivos de drenagem provisória, redirecionando o fluxo para bacias de sedimentação ou pontos de lançamento autorizados; (ii) implantar/recompor valetas, canaletas e dissipadores de energia que reduzam a velocidade e retenham sólidos antes do lançamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e, quando aplicável, verificação sob chuva, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-03' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver processo erosivo instalado (sulcos, ravinas ou início de voçoroca) ou instabilidade de talude que ameace estruturas, vias ou a segurança de trabalhadores.',
  texto_fundamentacao_normativa = 'O controle de erosão exige proteção efetiva das superfícies e taludes expostos por meio de dissipadores de energia, revegetação, cobertura vegetal ou geossintéticos, evitando o desencadeamento e a evolução de processos erosivos. O requisito decorre das condicionantes ambientais da obra, do plano de controle de erosão e assoreamento e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, apoiando-se em boas práticas de proteção de solos e taludes. O critério "Proteção de taludes, dissipadores, revegetação" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa, cuja eficácia deve ser comprovada em campo.',
  texto_risco_consequencia = 'A ausência ou insuficiência de medidas de controle de erosão leva à formação de sulcos, ravinas e instabilização de taludes, com perda de solo, assoreamento de drenagens e corpos hídricos e comprometimento de estruturas adjacentes, gerando retrabalho, sobrecusto e exposição a autuação ambiental. A permanência da condição permite a progressão do processo erosivo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) proteger imediatamente as superfícies e taludes expostos com revegetação, cobertura, biomantas ou solução equivalente prevista em projeto; (ii) implantar dissipadores de energia e disciplinar o escoamento superficial para interromper o carreamento de solo e conformar a geometria dos taludes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e acompanhamento da estabilização, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-03' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — pela proximidade direta com corpo hídrico; rebaixar a Maior somente se a barreira estiver instalada e íntegra, com falha meramente pontual de manutenção sem carreamento ativo de sedimentos ao curso d''água.',
  texto_fundamentacao_normativa = 'As barreiras de sedimentação (barreiras de siltagem, bermas filtrantes ou cortinas de contenção) devem ser instaladas a montante dos corpos hídricos próximos para reter sólidos em suspensão antes que atinjam a água, mantendo-se íntegras e periodicamente limpas. O requisito decorre das condicionantes do licenciamento ambiental, do plano de controle de sedimentos e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, apoiado em boas práticas de proteção de recursos hídricos. O critério "Barreiras de siltagem em corpos hídricos próximos" integra o plano de inspeção e constitui requisito verificável de aceitação, exigindo comprovação de presença, posicionamento e integridade das barreiras.',
  texto_risco_consequencia = 'A inexistência, o posicionamento incorreto ou a colmatação das barreiras de sedimentação permite o aporte direto de sólidos ao corpo hídrico, causando assoreamento, turbidez e dano à fauna aquática, além de expor a obra a autuação e embargo por infração ambiental. A permanência da condição mantém ativo o risco de contaminação do curso d''água a cada evento de escoamento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar ou reposicionar as barreiras de siltagem a montante do corpo hídrico, conforme o projeto e as condicionantes ambientais; (ii) executar a limpeza e a manutenção das barreiras existentes, removendo o material retido e recompondo trechos danificados ou colmatados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e checagem da integridade após instalação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-03' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — por caracterizar lançamento irregular de efluente; manter Crítica sempre que houver descarte ativo em solo ou corpo d''água, rebaixando a Maior apenas se for risco iminente já contido, sem lançamento consumado.',
  texto_fundamentacao_normativa = 'Os efluentes gerados na obra (sanitários, de lavagem, oleosos ou de processos) não podem ser lançados diretamente no solo ou em corpos d''água sem tratamento e sem atendimento aos padrões e condições de lançamento. A Resolução CONAMA nº 430/2011 dispõe sobre as condições e padrões de lançamento de efluentes, e o requisito é reforçado pelas condicionantes do licenciamento ambiental e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Efluentes não lançados em solo/corpos d''água" integra o plano de inspeção e constitui requisito verificável de aceitação, exigindo destinação a sistema de tratamento ou coleta autorizada.',
  texto_risco_consequencia = 'O lançamento irregular de efluentes contamina solo, lençol freático e corpos d''água, com dano ambiental de difícil reversão, risco sanitário e enquadramento como crime ambiental, sujeitando a obra a multas, embargo e responsabilização. A permanência da condição mantém ativo o processo de contaminação enquanto persistir o descarte até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper de imediato qualquer lançamento em solo ou corpo d''água e conter/recolher o efluente já disperso; (ii) direcionar os efluentes para sistema de tratamento adequado, coleta por empresa licenciada ou ponto de lançamento autorizado, conservando os comprovantes de destinação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e documentação da destinação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-03' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a caixa separadora estiver saturada, transbordando ou inoperante, permitindo passagem de óleo para a drenagem ou o solo em áreas de lavagem e abastecimento.',
  texto_fundamentacao_normativa = 'As caixas separadoras de água e óleo (SAO) das áreas de lavagem de veículos e abastecimento devem estar limpas e em funcionamento, retendo óleos e graxas antes do lançamento do efluente à rede ou ao ponto de destinação. O requisito decorre das condicionantes ambientais da obra, do plano de gestão de efluentes oleosos e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, complementado por boas práticas de operação e manutenção de SAO. O critério "Limpeza e funcionamento (lavagem/abastecimento)" integra o plano de inspeção e constitui requisito verificável de aceitação, exigindo comprovação de manutenção periódica e destinação adequada do resíduo oleoso retido.',
  texto_risco_consequencia = 'A caixa separadora suja, saturada ou inoperante deixa de reter óleos e graxas, permitindo que o efluente oleoso alcance a drenagem, o solo ou corpos d''água, com contaminação ambiental, risco de autuação e comprometimento do licenciamento. A permanência da condição mantém ativo o risco de lançamento de óleo a cada operação de lavagem ou abastecimento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realizar a limpeza da caixa separadora, removendo o óleo e o material retido e restabelecendo o nível operacional dos compartimentos; (ii) verificar e recompor o funcionamento do dispositivo, destinando o resíduo oleoso a empresa licenciada com o respectivo comprovante e instituindo rotina de manutenção periódica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e comprovante de destinação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-03' and item_numero = 5;

-- MA-04 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter a classificação sempre que houver supressão fora do polígono licenciado; rebaixar a Maior apenas se o excedente for pontual, contido em faixa já prevista no projeto, e houver anuência formal do órgão licenciador.',
  texto_fundamentacao_normativa = 'A supressão de vegetação só pode ocorrer mediante Autorização de Supressão de Vegetação (ASV) emitida pelo órgão ambiental competente e restrita ao polígono efetivamente licenciado, condição integrante do licenciamento ambiental do empreendimento. Aplicam-se a Lei nº 12.651/2012 (Código Florestal), a Lei nº 6.938/1981 (Política Nacional do Meio Ambiente) e as condicionantes da licença/ASV, cabendo confronto do limite executado com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que delimita a área de intervenção. O critério "Somente na área licenciada (ASV)" constitui requisito legal e verificável de aceitação, comprovável por levantamento topográfico do polígono suprimido.',
  texto_risco_consequencia = 'A supressão executada fora da área autorizada configura intervenção não licenciada, sujeita a embargo, autuação e multa pelo órgão ambiental e, conforme o caso, a responsabilização criminal nos termos da Lei nº 9.605/1998, além de dano à biodiversidade e à cobertura vegetal remanescente, de difícil ou impossível reparação. A permanência da condição amplia a área impactada e agrava o passivo ambiental do empreendimento até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender de imediato qualquer supressão fora do polígono licenciado, isolando e sinalizando o limite da ASV; (ii) confrontar topograficamente a área efetivamente suprimida com o polígono da ASV e o projeto executivo aprovado, identificando e quantificando eventual excedente; (iii) comunicar formalmente o órgão licenciador, adotar as medidas compensatórias/reparadoras determinadas e evidenciar a demarcação corrigida do limite com registro fotográfico ({{evidencia_foto_correcao}}) e nova conferência topográfica, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-04' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter quando houver intervenção, supressão ou lançamento de material dentro de Área de Preservação Permanente; rebaixar a Maior apenas se restrita a aproximação de maquinário sem dano à vegetação ou ao solo da APP.',
  texto_fundamentacao_normativa = 'As Áreas de Preservação Permanente (APP) — faixas marginais de cursos d''água, nascentes, encostas e demais hipóteses legais — devem ser delimitadas em campo e respeitadas, admitindo-se intervenção apenas nas hipóteses e condições expressamente autorizadas no licenciamento. Aplicam-se a Lei nº 12.651/2012 (Código Florestal), que define e protege as APP, e as condicionantes da licença ambiental, cabendo a locação das faixas conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Áreas de preservação delimitadas e respeitadas" é requisito verificável, comprovável pela sinalização física da APP e pela ausência de intervenção não autorizada em seu interior.',
  texto_risco_consequencia = 'A supressão de vegetação, o trânsito de máquinas ou o lançamento de solo e resíduos em APP compromete funções ambientais essenciais — estabilidade de margens, proteção de nascentes e recursos hídricos e conservação da fauna — e sujeita o empreendimento a embargo, autuação e responsabilização nos termos da Lei nº 9.605/1998, com passivo ambiental de recuperação onerosa. A permanência da condição mantém ativa a degradação da faixa protegida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) cessar imediatamente qualquer intervenção no interior da APP e demarcar/sinalizar fisicamente suas faixas conforme o projeto e a legislação; (ii) remover material eventualmente lançado e avaliar, com responsável técnico, a necessidade de recuperação da área afetada (recomposição vegetal ou estabilização de margem); (iii) evidenciar a delimitação e a recuperação com registro fotográfico ({{evidencia_foto_correcao}}) e croqui de locação das faixas, comunicando o órgão licenciador quando exigido e submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-04' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a emissão de poeira atingir receptores sensíveis (residências, vias públicas, unidades de saúde) ou reduzir a visibilidade em vias de tráfego, comprometendo a segurança.',
  texto_fundamentacao_normativa = 'O controle de emissão de material particulado (poeira) em vias não pavimentadas, frentes de terraplenagem e áreas de estoque é medida obrigatória de gestão ambiental da obra, executada por umectação sistemática e limitação de velocidade da frota. Na ausência de norma técnica específica de citação segura para este item, a exigência fundamenta-se no critério "Umectação de vias, controle de velocidade", nas condicionantes da licença ambiental / Plano de Controle Ambiental e nas boas práticas de engenharia, sendo requisito verificável pela existência e regularidade das ações de umectação e da sinalização de velocidade.',
  texto_risco_consequencia = 'A ausência de controle de poeira gera dispersão de material particulado que afeta a qualidade do ar, a saúde de trabalhadores e da vizinhança, deposita-se sobre culturas e edificações e reduz a visibilidade nas vias internas, aumentando o risco de acidentes e ensejando reclamações e autuações ambientais. A permanência da condição mantém a exposição continuada de receptores à poeira. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) restabelecer a umectação programada das vias e frentes de serviço, com frequência compatível com o clima e o tráfego, registrando os horários de aplicação; (ii) implantar e fiscalizar a limitação de velocidade da frota por sinalização e, quando cabível, por medidas físicas (lombadas/redutores); (iii) evidenciar a execução com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de controle das umectações, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-04' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em caso de reincidência ou de emissão que ultrapasse de forma persistente o grau de referência da Escala de Ringelmann; rebaixar a Observação se pontual e sanada de imediato pela regulagem do motor.',
  texto_fundamentacao_normativa = 'A emissão de fumaça preta por motores a diesel de máquinas e equipamentos deve ser controlada e mantida dentro do grau de referência da Escala de Ringelmann, indicador visual consolidado de densidade de fumaça, sustentado por manutenção preventiva dos motores. A exigência fundamenta-se no critério "Escala de Ringelmann, manutenção de motores", nas condicionantes da licença ambiental e no plano de manutenção da frota; não se cita número de norma por cautela quanto à sua aplicabilidade específica a equipamentos de obra. Trata-se de requisito verificável por avaliação visual com a Escala de Ringelmann e pela existência de registros de manutenção dos equipamentos.',
  texto_risco_consequencia = 'A emissão excessiva de fumaça preta indica combustão deficiente e má regulagem do motor, lançando poluentes que degradam a qualidade do ar e a saúde de trabalhadores e da vizinhança, além de sinalizar consumo e desgaste anormais do equipamento e expor a obra a autuação ambiental. A permanência da condição mantém a fonte poluidora em operação irregular. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de operação o equipamento que exceda o grau de referência da Escala de Ringelmann e submetê-lo a manutenção corretiva (injeção, filtros e regulagem do motor); (ii) reavaliar a emissão com a Escala de Ringelmann após a manutenção e reforçar o plano de manutenção preventiva da frota; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e cópia da ordem de serviço de manutenção, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-04' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o ruído ultrapassar os limites em receptores sensíveis, ocorrer em horário de descanso (noturno) ou expor trabalhadores acima do limite de tolerância ocupacional.',
  texto_fundamentacao_normativa = 'A geração de ruído pelas atividades da obra deve observar os horários permitidos e os limites aplicáveis, tanto para a vizinhança quanto para os trabalhadores. Para o ruído comunitário aplica-se a NBR 10151 (avaliação de ruído em áreas habitadas), e para a exposição ocupacional aplicam-se os limites de tolerância da NR-15; somam-se as condicionantes da licença ambiental e as posturas municipais quanto a horários. O critério "Horários e limites respeitados" é requisito verificável por medição de nível de pressão sonora e pelo cumprimento da janela de horário autorizada.',
  texto_risco_consequencia = 'O ruído acima dos limites ou fora dos horários permitidos causa incômodo e perturbação à vizinhança, ensejando reclamações e autuações, e, no ambiente de trabalho, expõe os trabalhadores a risco de perda auditiva induzida por ruído. A permanência da condição mantém a comunidade e a equipe expostas a níveis sonoros inadequados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) restringir as atividades ruidosas à janela de horário autorizada e adotar medidas de atenuação na fonte (enclausuramento, silenciadores, barreiras); (ii) medir os níveis de pressão sonora nos receptores e nas frentes, comparando-os aos limites aplicáveis, e assegurar o uso de protetor auditivo pelos expostos; (iii) evidenciar as medidas com registro fotográfico ({{evidencia_foto_correcao}}) e laudo/planilha de medição sonora, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-04' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em caso de captura, morte ou maus-tratos de fauna, ou de risco iminente à equipe por animal peçonhento; rebaixar a Observação se houver apenas lacuna documental do procedimento, sem ocorrência registrada.',
  texto_fundamentacao_normativa = 'A obra deve dispor de procedimento formal de registro, monitoramento e afugentamento/resgate de fauna silvestre e de manejo seguro de animais peçonhentos, acionado antes e durante as frentes de supressão e movimentação de terra. A exigência fundamenta-se no critério "Procedimento para animais silvestres/peçonhentos", nas condicionantes da licença ambiental (programas de afugentamento e resgate de fauna) e no Programa de Gerenciamento de Riscos da obra; não se cita número de norma para preservar a certeza da referência. É requisito verificável pela existência do procedimento, dos registros de fauna e da capacitação da equipe.',
  texto_risco_consequencia = 'A ausência de procedimento de fauna expõe animais silvestres a morte e afastamento de habitat durante a intervenção, configurando dano ambiental e descumprimento de condicionante, e expõe os trabalhadores a acidentes com animais peçonhentos (serpentes, aranhas, escorpiões), com risco à vida. A permanência da condição mantém simultaneamente a fauna e a equipe desprotegidas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar/formalizar o procedimento de registro e afugentamento de fauna e de manejo de animais peçonhentos, com fluxo de acionamento e responsáveis definidos; (ii) capacitar as equipes, disponibilizar contatos de resgate e vistoriar as frentes antes da supressão, mantendo registro das ocorrências; (iii) evidenciar a implantação com registro fotográfico ({{evidencia_foto_correcao}}) e cópia do procedimento e da lista de presença da capacitação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-04' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter sempre que houver condicionante ambiental vencida ou não atendida com prazo esgotado; rebaixar a Maior apenas se o atendimento estiver em andamento dentro do prazo e integralmente documentado.',
  texto_fundamentacao_normativa = 'As condicionantes estabelecidas na licença ambiental são obrigações vinculantes cujo cumprimento e comprovação, em prazo, são condição de validade da licença e de regularidade do empreendimento. Aplicam-se a Lei nº 6.938/1981 (Política Nacional do Meio Ambiente) e a Resolução CONAMA nº 237/1997 (licenciamento ambiental), que dão base ao regime de licenciamento e às condicionantes, além do próprio texto da licença emitida. O critério "Checklist das condicionantes ambientais em dia" é requisito verificável pela existência de controle atualizado das condicionantes, com evidências e prazos de cada obrigação.',
  texto_risco_consequencia = 'O descumprimento ou a perda de prazo de condicionantes ambientais sujeita o empreendimento a advertência, multa, suspensão ou cassação da licença e embargo da obra, além de comprometer a rastreabilidade das obrigações e a imagem institucional perante o órgão ambiental. A permanência da condição mantém o empreendimento em situação de irregularidade e sob risco de sanção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revisar o checklist de condicionantes, identificando as pendentes, vencidas ou sem evidência, com respectivos prazos e responsáveis; (ii) providenciar o atendimento e a protocolização das comprovações junto ao órgão licenciador, solicitando prorrogação formal quando o prazo for inviável; (iii) evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}) e cópia dos protocolos de atendimento das condicionantes, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'MA-04' and item_numero = 7;

-- PR-01 (9 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio entre avanço real e planejado atingir o caminho crítico ou marcos contratuais de entrega',
  texto_fundamentacao_normativa = 'O acompanhamento do avanço físico real confrontado ao planejado é instrumento essencial de controle do empreendimento, permitindo detectar desvios de prazo e subsidiar decisões de recuperação. O critério "Avanço físico real × planejado registrado" integra o plano de gestão da obra e constitui requisito verificável de aceitação do processo de controle. A fundamentação apoia-se nas boas práticas de gerenciamento de cronograma e na linha de base do planejamento contratual aprovado; por se tratar de requisito de gestão, não se ampara em número de norma específico.',
  texto_risco_consequencia = 'A ausência de cronograma atualizado impede a identificação tempestiva de atrasos e a adoção de medidas de recuperação, permitindo a propagação silenciosa de desvios ao caminho crítico e o comprometimento de marcos contratuais, com risco de multas e sobrecusto. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) atualizar o cronograma físico com a medição do avanço real por frente/atividade, confrontando-o à linha de base planejada; (ii) identificar os desvios, registrar as causas e propor plano de recuperação para as atividades do caminho crítico; (iii) evidenciar a atualização com o registro da curva S e do relatório de medição ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'PR-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o bloqueio impedir o início de atividade do caminho crítico ou expuser equipes a risco de segurança',
  texto_fundamentacao_normativa = 'A liberação das frentes de serviço, isenta de bloqueios documentais (licenças, projetos, autorizações) e técnicos (interferências, condições de acesso), é condição prévia para a produção sem interrupções. O critério "Sem bloqueios documentais/técnicos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação para a mobilização das equipes. A fundamentação apoia-se nas boas práticas de planejamento e liberação de frentes e nos requisitos do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, dispensando citação de número de norma por se tratar de requisito de gestão de produção.',
  texto_risco_consequencia = 'Frentes liberadas com bloqueios pendentes resultam em paralisações, retrabalho e ociosidade de equipes e equipamentos, além de possível execução em desacordo com licenças e projeto, com impacto direto de prazo e custo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inventariar os bloqueios documentais e técnicos de cada frente, atribuindo responsável e prazo de tratamento; (ii) condicionar a mobilização à efetiva liberação, com checklist de pré-requisitos concluído; (iii) evidenciar a liberação com o termo/registro de frente liberada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'PR-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a falta de material paralisar frente do caminho crítico ou comprometer marco contratual',
  texto_fundamentacao_normativa = 'A disponibilidade de materiais em quantidade e especificação compatíveis com o planejamento assegura a continuidade da produção e a aderência ao cronograma. O critério "Sem paradas por falta de material" integra o controle de suprimentos da obra e constitui requisito verificável de aceitação do processo logístico. A fundamentação apoia-se nas boas práticas de gestão de suprimentos e curva de aprovisionamento e nas especificações de material do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, sem apoio em número de norma específico por se tratar de requisito de gestão.',
  texto_risco_consequencia = 'A indisponibilidade de materiais provoca paralisação de frentes, ociosidade de mão de obra e equipamentos e ruptura da sequência construtiva, gerando atraso de cronograma e sobrecusto por improdutividade. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar os materiais críticos em falta e confrontar saldos com a curva de aprovisionamento e o cronograma; (ii) emitir ou reprogramar pedidos de compra e ajustar prazos de entrega com os fornecedores, priorizando frentes do caminho crítico; (iii) evidenciar a regularização com o registro de recebimento/estoque ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'PR-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a indisponibilidade de equipamento impedir atividade do caminho crítico ou comprometer as condições de segurança da operação',
  texto_fundamentacao_normativa = 'A disponibilidade de equipamentos em quantidade e capacidade compatíveis com o plano de ataque é requisito para o atendimento das produtividades previstas. O critério "Disponibilidade compatível com o plano" integra o planejamento de recursos da obra e constitui requisito verificável de aceitação. A fundamentação apoia-se nas boas práticas de dimensionamento e gestão de equipamentos e no plano de execução aprovado, dispensando citação de número de norma por se tratar de requisito de gestão de recursos.',
  texto_risco_consequencia = 'Equipamentos indisponíveis ou incompatíveis com o plano reduzem a produtividade das frentes, geram gargalos na sequência construtiva e podem impor soluções improvisadas, com impacto de prazo, custo e segurança. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a frota disponível e operante com o dimensionamento previsto por frente/atividade; (ii) providenciar substituição, manutenção ou mobilização adicional dos equipamentos faltantes, priorizando o caminho crítico; (iii) evidenciar a regularização com o registro de mobilização e checklist de equipamento ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'PR-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver execução em curso a partir de revisão superada, com risco de retrabalho ou não conformidade estrutural',
  texto_fundamentacao_normativa = 'A disponibilização, nas frentes, da última revisão válida dos projetos evita a execução a partir de documentos superados e assegura a rastreabilidade das alterações. O critério "Última revisão distribuída" integra o controle de documentos da obra e constitui requisito verificável de aceitação. Aplica-se o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define a versão vigente para execução; a fundamentação apoia-se nas boas práticas de gestão e controle de documentos, sem citação de número de norma específico.',
  texto_risco_consequencia = 'A permanência de revisões superadas nas frentes induz execução em desacordo com o projeto vigente, gerando retrabalho, não conformidades e possível comprometimento de interfaces e do desempenho estrutural, com sobrecusto e atraso. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar, em cada frente, a revisão em uso frente à lista mestra de documentos vigente; (ii) recolher e inutilizar cópias superadas e distribuir a última revisão aprovada, registrando o protocolo de distribuição; (iii) evidenciar a atualização com o registro do carimbo de revisão vigente na frente ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'PR-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a interferência não tratada afetar redes existentes, segurança de terceiros ou atividade do caminho crítico',
  texto_fundamentacao_normativa = 'O registro e o plano de solução das interferências (entre disciplinas, com redes existentes ou com terceiros) são requisitos para a compatibilização e a execução segura das frentes. O critério "Registro e plano de solução" integra o processo de compatibilização e gestão de interferências da obra e constitui requisito verificável de aceitação. A fundamentação apoia-se nas boas práticas de compatibilização de projetos e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, sem apoio em número de norma específico por se tratar de requisito de gestão.',
  texto_risco_consequencia = 'Interferências não tratadas provocam paralisações, retrabalho de compatibilização e execução conflitante entre disciplinas ou com redes existentes, com risco de danos a terceiros, acidentes e impacto de prazo e custo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) registrar formalmente cada interferência identificada, com localização e disciplinas envolvidas; (ii) elaborar e aprovar o plano de solução, com responsável e prazo, antes da liberação da frente afetada; (iii) evidenciar o tratamento com o registro da solução implantada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'PR-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando as pendências sem responsável ou prazo recaírem sobre frentes ativas ou marcos contratuais',
  texto_fundamentacao_normativa = 'O mapeamento das pendências com responsável e prazo definidos assegura o encaminhamento e o encerramento tempestivo das ações em aberto. O critério "Lista de pendências com responsável e prazo" integra a rotina de gestão da obra e constitui requisito verificável de aceitação do controle de ações. A fundamentação apoia-se nas boas práticas de gestão de pendências (listas de pendências/punch list) e no plano de gestão da obra, sem citação de número de norma por se tratar de requisito de gestão.',
  texto_risco_consequencia = 'Pendências sem responsável e prazo definidos tendem a permanecer indefinidamente em aberto, acumulando-se e migrando para etapas subsequentes ou para a entrega, com risco de retrabalho tardio e comprometimento do recebimento da obra. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) consolidar a lista de pendências, atribuindo a cada item responsável e prazo de tratamento; (ii) estabelecer rotina de acompanhamento periódico do saldo, priorizando as pendências que afetam frentes ativas; (iii) evidenciar a organização com o registro da lista de pendências atualizada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'PR-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de apontamento impedir o controle de frentes do caminho crítico ou a medição contratual',
  texto_fundamentacao_normativa = 'O apontamento dos índices de produtividade por equipe/atividade no RDO (Relatório Diário de Obra) permite comparar o desempenho real ao previsto e subsidiar a gestão de recursos e prazos. O critério "Índices por equipe/atividade apontados no RDO" integra a rotina de controle da obra e constitui requisito verificável de aceitação. A fundamentação apoia-se nas boas práticas de apropriação de mão de obra e no papel do RDO como registro oficial da obra, sem citação de número de norma específico por se tratar de requisito de gestão e contratual.',
  texto_risco_consequencia = 'A falta de registro de produtividade impede a detecção de desvios de desempenho e o correto dimensionamento de equipes, mascarando perdas e dificultando a medição e a tomada de decisão, com risco de atraso e sobrecusto. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) padronizar o apontamento diário dos índices de produtividade por equipe/atividade no RDO; (ii) confrontar os índices reais com os previstos e tratar os desvios relevantes junto às frentes; (iii) evidenciar a regularização com o registro do RDO preenchido ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'PR-01' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o subdimensionamento do efetivo inviabilizar marco contratual ou comprometer as condições de segurança',
  texto_fundamentacao_normativa = 'A compatibilidade do efetivo real com o previsto no histograma de mão de obra é condição para o atendimento das produtividades e prazos planejados. O critério "Histograma real × previsto" integra o planejamento de recursos da obra e constitui requisito verificável de aceitação. A fundamentação apoia-se nas boas práticas de dimensionamento de mão de obra e no plano de execução/histograma aprovado, dispensando citação de número de norma por se tratar de requisito de gestão de recursos.',
  texto_risco_consequencia = 'Efetivo incompatível com o plano compromete o atendimento das produtividades e do cronograma; o subdimensionamento gera atrasos e o superdimensionamento eleva custos e pode saturar as frentes, com reflexos de prazo, custo e segurança. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar o efetivo real por categoria com o histograma previsto, identificando as defasagens; (ii) ajustar a alocação de mão de obra (mobilização, remanejamento ou desmobilização), priorizando as frentes do caminho crítico; (iii) evidenciar a adequação com o registro do histograma atualizado real × previsto ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'PR-01' and item_numero = 9;

-- QA-01 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o material recebido sem inspeção houver sido liberado para aplicação em elementos estruturais, de vedação estanque ou de segurança, ou quando divergir do pedido em característica que impeça seu uso na frente.',
  texto_fundamentacao_normativa = 'A inspeção de recebimento é a barreira de controle que assegura que o material entregue corresponde, em tipo, quantidade, marca, dimensão e classe, ao pedido de compra e à especificação técnica do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Trata-se de requisito do sistema de gestão da qualidade da obra, alinhado à NBR ISO 9001 no que concerne ao controle de produtos e serviços providos externamente, e integra o plano de inspeção como ponto de verificação de aceitação anterior à liberação para uso. O critério "Materiais conferidos contra pedido/especificação" constitui condição verificável e documentável de aceitação do lote no canteiro.',
  texto_risco_consequencia = 'A dispensa ou a falha da inspeção de recebimento permite o ingresso de material divergente, avariado ou fora de especificação na obra, que, uma vez incorporado, exige remoção e retrabalho, gera sobrecusto, atrasa o cronograma e pode comprometer o desempenho do elemento executado. Enquanto não sanada, a condição mantém em risco a conformidade de todo o lote recebido. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) segregar e identificar o lote recebido, suspendendo sua liberação para uso até a conferência; (ii) conferir item a item contra o pedido de compra e a especificação do projeto, registrando divergências de tipo, quantidade, marca, dimensão e classe, e tratar o material não conforme com o fornecedor (devolução ou substituição); (iii) formalizar o resultado da inspeção de recebimento em registro específico e evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o material sem certificado arquivado já estiver aplicado em elemento estrutural ou de segurança, tornando impossível comprovar a posteriori sua conformidade e a origem dos ensaios.',
  texto_fundamentacao_normativa = 'Os certificados de qualidade e os relatórios de ensaio dos materiais constituem a evidência objetiva de que o produto atende às normas de produto e à especificação técnica, e devem ser retidos como informação documentada da obra, conforme os princípios da NBR ISO 9001 aplicáveis à retenção de registros. Vinculados ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, os certificados sustentam a decisão de aceitação e viabilizam auditoria e rastreabilidade posterior. O critério "Certificados de qualidade/ensaios arquivados" é requisito verificável de aceitação, pois sem o documento não há como comprovar a conformidade do material efetivamente empregado.',
  texto_risco_consequencia = 'A ausência ou o não arquivamento dos certificados impede comprovar que o material atende à especificação e aos ensaios exigidos, fragiliza a defesa técnica da obra em auditorias e recebimentos, e, na hipótese de falha futura, inviabiliza a identificação da causa e a responsabilização do fornecedor. A condição mantém o material em situação de conformidade não demonstrável enquanto perdurar. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) obter junto ao fornecedor os certificados de qualidade e relatórios de ensaio correspondentes aos lotes efetivamente recebidos, conferindo a correspondência de lote, data e características; (ii) organizar e arquivar os documentos no dossiê da qualidade da obra, vinculando cada certificado ao respectivo lote e frente de aplicação; (iii) evidenciar o arquivamento com registro fotográfico ou digitalização ({{evidencia_foto_correcao}}) e submeter à reinspeção documental para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o armazenamento inadequado houver comprometido material sensível a intempéries ou com prazo de validade vencido (aglomerantes, adesivos, selantes), inviabilizando seu uso com segurança.',
  texto_fundamentacao_normativa = 'O armazenamento conforme as instruções do fabricante preserva as propriedades físico-químicas e o desempenho do material até o momento da aplicação, protegendo-o de umidade, intempéries, contaminação e ação do tempo, e respeitando o prazo de validade. Aplicam-se as instruções técnicas do fabricante e as boas práticas de gestão de materiais em canteiro, em consonância com os requisitos de preservação de produto da NBR ISO 9001 e com a especificação do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Proteção contra intempéries, prazo de validade" é requisito verificável de aceitação da condição de estoque.',
  texto_risco_consequencia = 'O armazenamento em desacordo com o fabricante degrada o material — empedramento de aglomerantes, oxidação, absorção de umidade, perda de aderência ou vencimento de validade —, de modo que, aplicado nessa condição, resulta em desempenho aquém do especificado, patologias precoces e retrabalho. A permanência do desvio mantém o estoque exposto e amplia a fração de material comprometido. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) adequar o local de estocagem às instruções do fabricante (estrados/paletes, cobertura, ventilação, afastamento do solo e das paredes, proteção contra intempéries) e segregar o material com validade vencida ou degradado; (ii) implantar controle de validade e giro de estoque (PEPS), descartando ou devolvendo o material impróprio; (iii) evidenciar a adequação com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção das condições de armazenamento para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a perda de rastreabilidade impedir vincular material já aplicado a seu lote e frente, inviabilizando ação corretiva dirigida ou recolhimento em caso de não conformidade detectada.',
  texto_fundamentacao_normativa = 'A rastreabilidade assegura que cada lote de material recebido possa ser identificado e vinculado à frente de serviço em que foi aplicado, permitindo, diante de qualquer não conformidade, delimitar com precisão o universo afetado e dirigir a ação corretiva. Constitui requisito de identificação e rastreabilidade do sistema de gestão da qualidade, alinhado à NBR ISO 9001, e apoia-se na correlação entre notas fiscais, certificados de lote e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Lotes identificados e vinculados às frentes" é requisito verificável de aceitação do controle de materiais.',
  texto_risco_consequencia = 'Sem rastreabilidade, uma não conformidade posteriormente identificada em um lote não pode ser circunscrita, obrigando a inspeção ou substituição de extensão muito maior do que a efetivamente afetada, com sobrecusto e atraso, e comprometendo eventual recolhimento seletivo. A condição mantém indeterminado o vínculo material-frente enquanto não restabelecida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) restabelecer a identificação dos lotes em estoque e aplicados, correlacionando notas fiscais, certificados e registros de recebimento; (ii) implantar e manter o registro de vínculo lote-frente (planilha ou sistema), atualizado a cada liberação de material para uso; (iii) evidenciar a identificação e o vínculo com registro fotográfico das marcações e dos controles ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando material reprovado ou em análise, por falta de identificação e segregação, houver sido indevidamente liberado e aplicado na obra.',
  texto_fundamentacao_normativa = 'A identificação do status de inspeção — aprovado, em análise ou reprovado — e a segregação física do material impróprio impedem o uso inadvertido de produto não conforme ou ainda pendente de decisão. Trata-se de requisito de identificação do status de inspeção e de controle de saídas não conformes do sistema de gestão da qualidade, alinhado à NBR ISO 9001, e complementar à especificação do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Aprovado / em análise / reprovado segregado" é requisito verificável de aceitação da organização do estoque.',
  texto_risco_consequencia = 'A ausência de identificação de status e de segregação permite que material reprovado ou pendente de análise seja tomado como liberado e incorporado à obra, resultando em não conformidade de execução, retrabalho e possível comprometimento do elemento, além de misturar-se ao estoque aprovado. Enquanto não segregado e identificado, todo o material do local permanece sob risco de uso indevido. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar cada lote com seu status de inspeção (aprovado, em análise ou reprovado) por etiqueta, cor ou placa padronizada; (ii) segregar fisicamente em área demarcada o material reprovado e o em análise, impedindo sua retirada até a decisão, e tratar o reprovado (devolução, descarte ou reclassificação); (iii) evidenciar a identificação e a segregação com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção da organização do estoque para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-01' and item_numero = 5;

-- QA-02 (10 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver serviço em execução na frente sem projeto disponível ou apoiado em documento sem o carimbo ''válido para construção''.',
  texto_fundamentacao_normativa = 'A frente de serviço deve dispor de cópia controlada e legível do projeto na sua última revisão liberada, identificada com a condição ''válido para construção'', para que a execução reproduza fielmente o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A prática de controle da informação documentada assegura que a equipe de campo trabalhe sempre sobre a versão vigente e liberada. O critério "Última revisão, ''válido para construção''" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, evitando execução com base em documento não liberado.',
  texto_risco_consequencia = 'A ausência do projeto vigente na frente induz a execução por interpretação ou memória, gerando divergências em relação ao projeto executivo aprovado, com risco de não conformidade, retrabalho e demolição. A permanência da condição mantém a etapa exposta a decisões de campo sem respaldo documental até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) providenciar imediatamente na frente a cópia controlada do projeto na revisão vigente, com o carimbo ''válido para construção''; (ii) retirar de circulação eventuais cópias avulsas e conferir o serviço já executado contra a revisão correta; (iii) evidenciar a regularização com registro fotográfico do documento disponibilizado na frente ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se for identificada execução baseada em revisão obsoleta, com risco de incorporar solução superada ao serviço.',
  texto_fundamentacao_normativa = 'Somente a última revisão liberada do projeto pode subsidiar a execução; revisões obsoletas devem ser recolhidas e inutilizadas ou claramente identificadas como superadas. O confronto do número e da data de revisão em uso contra a lista mestra de documentos assegura o uso do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Sem uso de revisões obsoletas" é requisito verificável do plano de inspeção, pois a coexistência de versões antigas na obra é fonte direta de erro de execução.',
  texto_risco_consequencia = 'O uso de revisão obsoleta faz a obra incorporar soluções já alteradas ou canceladas, produzindo desvios em relação ao projeto vigente que só se revelam em etapas posteriores, quando a correção é mais onerosa. A permanência da condição mantém ativa a possibilidade de novos serviços executados sobre informação desatualizada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recolher e inutilizar (ou carimbar como ''obsoleto'') todas as cópias de revisões superadas em circulação na frente; (ii) confrontar o serviço executado com a revisão vigente, avaliando a necessidade de correção do que foi feito sob a revisão antiga; (iii) evidenciar o saneamento com registro fotográfico das cópias controladas atualizadas ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a divergência entre o instalado e o especificado afetar segurança, desempenho funcional ou intercambiabilidade do equipamento.',
  texto_fundamentacao_normativa = 'O equipamento ou instalação efetivamente montado deve corresponder ao especificado em projeto e na documentação técnica (folha de dados, lista de materiais e memorial), condição comprovada por verificação física confrontada com o documento. A conferência de marca, modelo, capacidade, material e posição garante aderência ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e às especificações técnicas contratadas. O critério "Verificação física × documento" integra o plano de inspeção e é requisito de aceitação da etapa, pois substituições não autorizadas descaracterizam a solução de projeto.',
  texto_risco_consequencia = 'Equipamento ou instalação em desacordo com a especificação pode não atender aos requisitos de desempenho, segurança e compatibilidade previstos, comprometendo a operação e podendo exigir substituição após a montagem. A permanência da condição mantém em serviço um item não conforme, com risco de propagação da divergência a interfaces e sistemas associados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar fisicamente o item instalado com a folha de dados, a lista de materiais e o projeto, identificando a divergência exata; (ii) substituir o item pelo especificado ou, havendo equivalência técnica, formalizar a análise de substituição para aprovação da fiscalização e do projetista; (iii) evidenciar a conformidade com registro fotográfico da placa/etiqueta de identificação e da instalação ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a ausência de controle dimensional recair sobre etapa que condiciona o apoio ou a interface de serviços subsequentes.',
  texto_fundamentacao_normativa = 'O controle dimensional da etapa deve ser executado e registrado por topografia e medições, produzindo evidência objetiva de que cotas, alinhamentos e níveis reproduzem o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O registro do levantamento e das medições constitui a evidência de aceitação geométrica da etapa e permite rastrear a conformidade após o encobrimento do serviço. O critério "Topografia e medições registradas" integra o plano de inspeção da obra e é requisito verificável, pois sem registro não há como comprovar o atendimento às tolerâncias de projeto.',
  texto_risco_consequencia = 'A falta de controle dimensional registrado deixa a etapa sem comprovação de que atende às cotas e tolerâncias de projeto, dificultando a detecção de desvios antes que sejam encobertos por serviços posteriores. A permanência da condição mantém o risco de acúmulo de erros geométricos ao longo da interface até a efetiva verificação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar o levantamento topográfico e as medições da etapa, confrontando cotas, níveis e alinhamentos com o projeto; (ii) formalizar o registro dimensional (planilha/relatório topográfico assinado) e tratar eventuais desvios identificados acima da tolerância; (iii) evidenciar a correção com registro fotográfico da atividade de medição e anexar o relatório topográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica quando o ensaio não realizado condiciona a liberação estrutural, elétrica ou de estanqueidade da etapa; rebaixar a Maior apenas para ensaios de caráter complementar.',
  texto_fundamentacao_normativa = 'Os ensaios e testes previstos (compactação, concreto, torque, megger, entre outros) devem ser realizados nos pontos e frequências definidos no PIT/ITP, com resultados dentro dos critérios de aceitação, antes da liberação da etapa. Aplicam-se as normas de ensaio próprias de cada disciplina — por exemplo, para concreto, a ABNT NBR 5739 (ensaio de compressão de corpos de prova cilíndricos) e a ABNT NBR 12655 (preparo, controle, recebimento e aceitação do concreto) — além do PIT/ITP e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Compactação, concreto, torque, megger, conforme PIT/ITP" é requisito de aceitação verificável, pois o ensaio é a evidência objetiva do desempenho especificado.',
  texto_risco_consequencia = 'A não realização (ou a não conformidade) dos ensaios libera a etapa sem comprovação de resistência, compactação, aperto ou isolamento, deixando incorporada à obra uma condição de desempenho não verificada e potencialmente insegura. A permanência da condição mantém a etapa aceita sob evidência insuficiente até a execução e aprovação dos ensaios pendentes. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar os ensaios e testes pendentes nos pontos e frequências do PIT/ITP, por laboratório/equipe habilitada, confrontando os resultados com os critérios de aceitação; (ii) tratar os resultados reprovados com a disposição cabível (reforço, refazimento ou reaperto), reensaiando após a correção; (iii) evidenciar a conformidade anexando os relatórios de ensaio e o registro fotográfico da execução dos testes ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se resultados de aceitação da obra tiverem sido emitidos com instrumento de certificado vencido, ausente ou fora da faixa de uso.',
  texto_fundamentacao_normativa = 'Os instrumentos de medição e ensaio empregados no controle da obra devem possuir certificado de calibração válido, com rastreabilidade metrológica a padrões reconhecidos, garantindo confiabilidade e incerteza compatível com a grandeza medida. A validade da calibração e a adequação da faixa de uso são condição para que os resultados de topografia, ensaios e verificações tenham valor de aceitação frente ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Certificados de calibração válidos" integra o plano de inspeção e é requisito verificável, pois medição feita com instrumento não calibrado não constitui evidência válida.',
  texto_risco_consequencia = 'O uso de instrumento sem calibração válida invalida as medições realizadas, podendo mascarar não conformidades ou reprovar indevidamente serviços conformes, e obriga a repetição das verificações afetadas. A permanência da condição contamina todos os registros produzidos com o instrumento no período sem certificado válido até a recalibração e reverificação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de uso o instrumento com calibração vencida/ausente e providenciar calibração em laboratório com rastreabilidade reconhecida; (ii) levantar as medições realizadas no período de invalidade e repetir aquelas críticas para a aceitação; (iii) evidenciar a regularização anexando o novo certificado de calibração e o registro fotográfico da etiqueta de calibração no instrumento ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver não conformidade detectada e não registrada, ou RNC aberta sem disposição definida sobre serviço já liberado.',
  texto_fundamentacao_normativa = 'Toda não conformidade identificada deve ser formalmente registrada em RNC e tratada até a definição e execução de sua disposição (correção, concessão, refazimento ou rejeição), assegurando rastreabilidade e o controle do produto não conforme. O tratamento documentado das RNC vincula o desvio ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e ao plano da qualidade da obra, evitando que serviços não conformes sejam liberados sem análise. O critério "Não conformidades registradas com disposição" é requisito verificável do plano de inspeção, pois a ausência de registro impede o controle e a análise de recorrência.',
  texto_risco_consequencia = 'Não conformidades não registradas ou sem disposição definida permanecem sem tratamento, permitindo que o desvio seja encoberto e se repita, sem análise de causa nem ação corretiva efetiva. A permanência da condição compromete a rastreabilidade da qualidade e mantém em aberto o risco de aceitação de serviço não conforme. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) registrar formalmente as não conformidades identificadas em RNC, com descrição, causa e classificação; (ii) definir e executar a disposição de cada RNC (correção, concessão formal, refazimento ou rejeição), com verificação de eficácia; (iii) evidenciar o tratamento anexando as RNC encerradas e o registro fotográfico das correções ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o retrabalho recorrente indicar causa sistêmica não tratada ou impacto relevante de custo e prazo não apropriado.',
  texto_fundamentacao_normativa = 'O retrabalho executado deve ser registrado com a identificação de sua causa e a apropriação do custo associado, permitindo a análise de recorrência e a atuação sobre a origem do desvio. O registro estruturado de causa e custo é a base para o controle de perdas e para a melhoria do processo, articulando-se ao plano da qualidade e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} quando a origem estiver em falha de execução ou interpretação. O critério "Causa e custo apontados" é requisito verificável de gestão, pois retrabalho sem registro impede quantificar perdas e corrigir a causa raiz.',
  texto_risco_consequencia = 'O retrabalho sem registro de causa e custo oculta a origem das falhas e o impacto financeiro real, impedindo a atuação sobre a causa raiz e permitindo a repetição do mesmo desvio em outras frentes. A permanência da condição mantém as perdas invisíveis à gestão e sem tratamento até a apropriação adequada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) registrar o retrabalho ocorrido, identificando a causa (análise de causa raiz) e apropriando o custo de mão de obra, material e equipamento; (ii) definir ação preventiva sobre a causa identificada para evitar recorrência em outras frentes; (iii) evidenciar o registro anexando o apontamento de causa/custo e o registro fotográfico do serviço refeito ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se a desatualização do RDO for reiterada ou impedir a comprovação contratual de fatos, ocorrências e efetivo da obra.',
  texto_fundamentacao_normativa = 'O Relatório Diário de Obra (RDO) deve ser preenchido diariamente, registrando efetivo, equipamentos, serviços executados, condições climáticas e ocorrências, constituindo o instrumento oficial de acompanhamento e a memória contratual da obra. O RDO é documento de valor contratual e probatório entre as partes, respaldando medições, pleitos e a rastreabilidade das decisões de campo relativas ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Diário de obra preenchido diariamente" é requisito verificável, pois o registro em atraso ou por memória compromete a fidelidade dos fatos anotados.',
  texto_risco_consequencia = 'O RDO desatualizado deixa a obra sem registro fiel e tempestivo dos fatos, fragilizando a comprovação de ocorrências, do efetivo e dos serviços em eventuais pleitos, medições ou controvérsias contratuais. A permanência da condição acumula lacunas de registro que dificilmente são reconstituídas com fidelidade após o transcurso dos dias. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) regularizar o preenchimento do RDO, recompondo, na medida do possível e com ressalva de data, os registros pendentes a partir de fontes confiáveis; (ii) estabelecer rotina diária de preenchimento e assinatura pelas partes responsáveis; (iii) evidenciar a regularização anexando os RDO atualizados e o registro fotográfico/print dos lançamentos ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior à medida que o atraso na consolidação do data book/as built se aproxima do comissionamento ou da entrega, quando a reconstituição documental se torna inviável.',
  texto_fundamentacao_normativa = 'O data book e o as built devem ser consolidados progressivamente durante a execução, reunindo certificados, ensaios, relatórios, RNC e as revisões que refletem o efetivamente construído, e não apenas ao final da obra. A consolidação contínua garante a rastreabilidade e a fidelidade do registro do que foi executado frente ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, incorporando tempestivamente as alterações de campo. O critério "Documentação sendo consolidada durante a obra" é requisito verificável, pois documentação deixada para o final tende a apresentar lacunas irrecuperáveis.',
  texto_risco_consequencia = 'A não consolidação tempestiva do data book/as built acumula pendências documentais que se tornam de difícil ou impossível reconstituição após o encobrimento dos serviços, comprometendo a entrega, o comissionamento e a operação futura da instalação. A permanência da condição amplia a lacuna documental a cada etapa concluída sem o correspondente registro consolidado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar as pendências documentais e organizar o data book/as built por disciplina, incorporando as alterações de campo já executadas; (ii) implantar rotina de consolidação concomitante à execução, com responsável e periodicidade definidos; (iii) evidenciar o avanço anexando o índice atualizado do data book e o registro fotográfico dos documentos consolidados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'QA-02' and item_numero = 10;

-- SO-01 (10 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver frentes sem qualquer acesso à água potável durante a jornada ou em dias de exposição térmica intensa, situação de risco iminente à saúde.',
  texto_fundamentacao_normativa = 'O fornecimento de água potável, fresca e em condições higiênicas em todas as frentes de trabalho é requisito de saúde ocupacional previsto na NR-24 (condições de higiene e conforto nos locais de trabalho), que veda o uso de copo coletivo e exige que a água esteja disponível em pontos próximos aos postos de trabalho. O critério "Fresca e acessível, copos individuais/garrafas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação das condições de vivência do canteiro.',
  texto_risco_consequencia = 'A ausência ou insuficiência de água potável e fresca nas frentes expõe o efetivo à desidratação e à queda de rendimento, e o uso de copo coletivo cria via de transmissão de doenças infectocontagiosas entre os trabalhadores. A permanência da condição mantém o efetivo desprotegido a cada jornada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar/repor pontos de água potável fresca dimensionados para o número de trabalhadores de cada frente, garantindo proximidade e acessibilidade; (ii) disponibilizar copos individuais descartáveis ou garrafas de uso pessoal, eliminando o copo coletivo, e definir rotina de reabastecimento e higienização dos recipientes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos pontos de água em operação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em caso de alimentos deteriorados, ausência de refrigeração ou infestação, por caracterizar risco direto de intoxicação alimentar coletiva.',
  texto_fundamentacao_normativa = 'O local destinado às refeições deve apresentar condições de higiene, conservação e limpeza, com preservação adequada dos alimentos, conforme a NR-24, que trata das instalações sanitárias e de conforto, incluindo refeitório. Boas práticas de manipulação e armazenamento de alimentos (controle de temperatura, proteção contra contaminação e limpeza de superfícies) complementam o requisito. O critério "Conservação de alimentos, limpeza" integra o plano de inspeção da obra e constitui requisito verificável de aceitação das áreas de vivência.',
  texto_risco_consequencia = 'Refeitório em más condições higiênicas e falha na conservação de alimentos favorecem a proliferação microbiana e a contaminação cruzada, com risco de intoxicação e doenças de veiculação alimentar capazes de afastar simultaneamente parte significativa do efetivo. A permanência da condição mantém ativo o risco sanitário a cada refeição servida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) higienizar o refeitório, superfícies e utensílios e restabelecer a rotina de limpeza com frequência definida e registro; (ii) corrigir a conservação dos alimentos (refrigeração, controle de temperatura e proteção contra vetores), descartando itens fora das condições de consumo; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do ambiente limpo e dos meios de conservação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando os sanitários estiverem inservíveis, sem água ou sem descarte adequado, comprometendo a saúde coletiva e a dignidade do trabalhador.',
  texto_fundamentacao_normativa = 'As instalações sanitárias devem permanecer limpas, em funcionamento e abastecidas com água e material de higiene, em quantidade compatível com o efetivo, conforme a NR-24, que fixa as exigências de instalações sanitárias nos locais de trabalho. A higienização diária registrada é o meio de comprovação do atendimento contínuo. O critério "Higienização diária registrada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação das condições de vivência.',
  texto_risco_consequencia = 'Sanitários sujos, sem abastecimento de água ou material de higiene, e sem registro de limpeza diária tornam-se foco de transmissão de doenças gastrointestinais e infecciosas, além de comprometer as condições dignas de trabalho. A permanência da condição mantém o efetivo exposto ao risco sanitário até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) higienizar imediatamente os sanitários e restabelecer o abastecimento de água, papel higiênico, sabão e demais insumos; (ii) implantar e manter o cronograma de limpeza diária com folha de controle assinada e visível no local; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos sanitários limpos e abastecidos e cópia do registro de higienização, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em dias de calor extremo ou onda de calor com trabalhadores sintomáticos, por risco iminente de exaustão térmica e intermação.',
  texto_fundamentacao_normativa = 'O trabalho a céu aberto sob sobrecarga térmica exige medidas de controle como pausas para descanso, áreas sombreadas e hidratação, requisito tratado pela NR-21 (trabalhos a céu aberto) e pela avaliação de riscos do PGR da obra. O gerenciamento do calor deve considerar a intensidade da atividade e as condições ambientais do dia. O critério "Pausas, sombra e hidratação em dias quentes" integra o plano de inspeção da obra e constitui requisito verificável de aceitação das condições de trabalho.',
  texto_risco_consequencia = 'A falta de gestão do calor em dias quentes expõe os trabalhadores à sobrecarga térmica, com progressão de câimbras e exaustão para intermação, quadro potencialmente fatal, além de elevar a probabilidade de erros e acidentes por fadiga. A permanência da condição mantém o risco térmico ativo enquanto durar a exposição sem controle. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar regime de pausas de recuperação térmica em função da intensidade da tarefa e da temperatura do dia, com área de sombra/descanso próxima às frentes; (ii) reforçar a oferta de água fresca e a reposição de eletrólitos e orientar a equipe quanto aos sinais de alerta de doença por calor; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das áreas de sombra e dos pontos de hidratação e registro do quadro de pausas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando houver tarefas de esforço repetitivo ou manuseio de cargas sem rodízio, com trabalhadores relatando queixas osteomusculares.',
  texto_fundamentacao_normativa = 'A adequação ergonômica das atividades, incluindo a organização do trabalho e o rodízio em tarefas repetitivas ou de esforço físico intenso, é requisito da NR-17 (ergonomia), que orienta a adaptação das condições de trabalho às características psicofisiológicas dos trabalhadores. A análise ergonômica preliminar da tarefa embasa a definição de pausas e revezamento. O critério "Rodízio em tarefas repetitivas/pesadas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da organização do trabalho.',
  texto_risco_consequencia = 'A ausência de rodízio e de medidas ergonômicas em tarefas repetitivas e pesadas favorece a sobrecarga osteomuscular e o desenvolvimento de LER/DORT, com afastamentos, queda de produtividade e passivo trabalhista. A permanência da condição acumula dano cumulativo ao efetivo a cada ciclo de trabalho. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear as tarefas repetitivas e de levantamento/transporte de cargas e implantar rodízio de funções e pausas de recuperação; (ii) prover meios de auxílio mecânico e orientar posturas e técnicas seguras de movimentação, revisando a organização das equipes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos ajustes de posto e do quadro de rodízio, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando não houver material de primeiros socorros disponível ou pessoa treinada em turno com atividades de risco em andamento.',
  texto_fundamentacao_normativa = 'O local de trabalho deve dispor de material necessário à prestação de primeiros socorros, guardado em local adequado e aos cuidados de pessoa treinada para esse fim, requisito previsto na NR-7 (Programa de Controle Médico de Saúde Ocupacional). A validade dos itens do kit e a presença de socorrista por turno asseguram a resposta imediata a emergências. O critério "Kit completo e válido, pessoa treinada por turno" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da prontidão de emergência.',
  texto_risco_consequencia = 'A falta de material de primeiros socorros completo e válido, ou a ausência de pessoa treinada por turno, retarda o atendimento inicial em acidentes e mal súbitos, agravando lesões e reduzindo as chances de estabilização até o socorro especializado. A permanência da condição mantém a obra sem capacidade de resposta imediata a cada turno. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recompor e conferir o kit de primeiros socorros, substituindo itens vencidos ou ausentes e definindo local sinalizado e de fácil acesso; (ii) designar e capacitar pelo menos um socorrista por turno, divulgando os contatos e a rota de emergência ao efetivo; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do kit conferido e comprovante de treinamento do responsável, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior na presença de focos de proliferação de vetores em áreas de vivência ou em período/região de surto de arboviroses.',
  texto_fundamentacao_normativa = 'O controle de insetos e vetores, com eliminação de focos de água parada e execução de dedetização periódica, é medida de higiene do canteiro e de proteção à saúde do efetivo, fundamentada nas boas práticas de saneamento e nas orientações da vigilância sanitária local, aliadas ao critério do item. Não se cita norma numerada específica por não haver requisito de numeração aplicável com certeza a esta atividade. O critério "Sem focos de água parada, dedetização" integra o plano de inspeção da obra e constitui requisito verificável de aceitação das condições sanitárias.',
  texto_risco_consequencia = 'A existência de focos de água parada e a ausência de controle de vetores favorecem a proliferação de mosquitos e a transmissão de arboviroses como dengue, além de exposição a outros insetos e roedores no canteiro, com risco de surto entre trabalhadores e comunidade lindeira. A permanência da condição mantém os criadouros ativos e o risco de infestação crescente. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) eliminar focos de água parada, promovendo drenagem, cobertura ou descarte de recipientes e adequação do armazenamento de materiais; (ii) executar dedetização/controle de vetores por empresa habilitada, com periodicidade definida e comprovante de aplicação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das áreas tratadas e o certificado do serviço, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em frentes de mata, terraplenagem ou áreas de alta incidência de peçonhentos sem rota de socorro definida ou acesso a soro.',
  texto_fundamentacao_normativa = 'O procedimento de resposta a acidentes com animais peçonhentos, incluindo orientação do efetivo, mapeamento da rota ao hospital de referência e a garantia de acesso à soroterapia, é medida de gestão de emergência baseada nas boas práticas de saúde ocupacional em obras a céu aberto e nas orientações dos protocolos de saúde pública, aliadas ao critério do item. Não se cita norma numerada específica por não haver requisito de numeração aplicável com certeza a esta atividade. O critério "Orientação, soro/rota ao hospital de referência mapeada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da prontidão de emergência.',
  texto_risco_consequencia = 'A ausência de procedimento estruturado para acidentes com serpentes, escorpiões e aranhas retarda o acesso à soroterapia específica, cujo tempo é determinante para a evolução do quadro, podendo resultar em agravamento clínico, sequelas ou óbito do acidentado. A permanência da condição mantém o efetivo sem plano de resposta a cada exposição em campo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar e divulgar procedimento de primeira resposta a acidentes com peçonhentos, orientando o efetivo quanto à conduta imediata e ao que não fazer; (ii) mapear e comunicar a rota e o hospital de referência com disponibilidade de soro antipeçonhento, mantendo contatos e transporte de emergência definidos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do procedimento afixado e da rota mapeada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior para trabalhadores expostos a ferimentos com material perfurocortante ou solo sem comprovação de imunização antitetânica em dia.',
  texto_fundamentacao_normativa = 'O acompanhamento da situação vacinal do efetivo, com destaque para a imunização antitetânica e a adesão às campanhas vigentes, é medida de proteção à saúde do trabalhador apoiada no acompanhamento de saúde ocupacional da obra e nas diretrizes de imunização da saúde pública, aliadas ao critério do item. Não se cita norma numerada específica por não haver requisito de numeração que imponha, com certeza, a vacinação do efetivo nesta atividade. A comprovação da vacinação em dia embasa a aptidão para atividades com risco de ferimentos e contaminação. O critério "Antitetânica e campanhas em dia" integra o plano de inspeção da obra e constitui requisito verificável de aceitação das condições de saúde do efetivo.',
  texto_risco_consequencia = 'A ausência de controle vacinal, em especial da antitetânica, deixa o trabalhador exposto ao tétano em caso de ferimentos com material contaminado, doença grave e de alta letalidade, além de fragilizar a resposta a surtos alcançados pelas campanhas. A permanência da condição mantém parcela do efetivo desprotegida a cada ferimento ocorrido em obra. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar a situação vacinal do efetivo e identificar os trabalhadores com antitetânica ou campanhas pendentes; (ii) encaminhar/organizar a atualização vacinal junto à rede de saúde e registrar os comprovantes no prontuário ocupacional; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a planilha de controle vacinal atualizada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em alojamentos superlotados, sem ventilação ou em condições insalubres que comprometam o descanso e a saúde dos trabalhadores.',
  texto_fundamentacao_normativa = 'Quando houver alojamento, as áreas de vivência devem atender a requisitos de camas adequadas, ventilação, iluminação e limpeza, condição prevista na NR-24 (áreas de vivência e alojamento), que fixa parâmetros de habitabilidade e higiene. A adequação do alojamento assegura descanso reparador e prevenção de agravos coletivos. O critério "Alojamento (se houver): camas, ventilação, limpeza" integra o plano de inspeção da obra e constitui requisito verificável de aceitação das áreas de vivência.',
  texto_risco_consequencia = 'Alojamento com camas inadequadas, ventilação deficiente ou falta de limpeza compromete o descanso do efetivo e favorece a transmissão de doenças respiratórias e infecciosas em ambiente coletivo, refletindo em fadiga acumulada e maior risco de acidentes. A permanência da condição mantém o efetivo em condições insalubres de repouso a cada pernoite. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) adequar o alojamento quanto a número e condição das camas, ventilação, iluminação e espaçamento, eliminando superlotação; (ii) implantar rotina de limpeza e higienização das áreas de vivência com registro e responsável definido; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do alojamento adequado e do controle de limpeza, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'SO-01' and item_numero = 10;

-- VE-01 (10 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a condução por motorista sem CNH válida ou de categoria incompatível com o veículo constitui impedimento imediato de operação, mantendo-se a Crítica sempre que o condutor não estiver formalmente autorizado pela empresa.',
  texto_fundamentacao_normativa = 'A condução de veículo exige Carteira Nacional de Habilitação válida e da categoria compatível com o tipo de veículo operado, conforme o Código de Trânsito Brasileiro (Lei nº 9.503/1997), que define as categorias de habilitação e as condições para dirigir. Soma-se a exigência interna de que o condutor esteja formalmente autorizado pela empresa e conste da relação de motoristas habilitados da obra. O critério "Categoria correta, motorista autorizado" integra o plano de inspeção de SSMA e constitui requisito verificável de liberação do veículo para uso.',
  texto_risco_consequencia = 'Permitir a condução por motorista sem CNH válida, com categoria incompatível ou não autorizado expõe a obra a acidentes por despreparo do condutor, além de autuações, apreensão do veículo e responsabilização civil e criminal da empresa e do gestor, com paralisação da operação e comprometimento da cobertura de seguro. Enquanto não regularizada, a condição mantém o veículo operando de forma irregular. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender de imediato a condução pelo motorista em situação irregular e recolher o veículo; (ii) verificar validade e categoria da CNH junto ao órgão de trânsito e designar condutor habilitado e formalmente autorizado, atualizando a relação de motoristas da obra; (iii) evidenciar a regularização com cópia da CNH válida e do registro de autorização ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência do checklist diário coincidir com defeito real em item de segurança (freios, pneus, direção ou iluminação) não detectado por falta da verificação prévia.',
  texto_fundamentacao_normativa = 'O preenchimento do checklist diário antes da saída do veículo é a barreira preventiva que assegura a identificação de anomalias antes do deslocamento, integrando o procedimento de gestão de frota e o plano de inspeção de SSMA da obra. Trata-se de requisito de boas práticas de manutenção preventiva e de controle documental de frota; o critério "Preenchido antes da saída" torna a verificação um requisito verificável de liberação diária, com registro que permite rastrear a condição do veículo ao longo do contrato.',
  texto_risco_consequencia = 'A não realização do checklist diário faz o veículo circular sem verificação prévia das condições de segurança, permitindo que defeitos progridam sem detecção até resultarem em falha em operação, com risco de acidente e indisponibilidade não programada da frota. A ausência de registro ainda impede a rastreabilidade da condição do veículo e a apuração de responsabilidades. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar e exigir o preenchimento do checklist diário antes de cada saída, com bloqueio da liberação do veículo sem o registro; (ii) capacitar condutores quanto aos itens a verificar e ao tratamento de não conformidades detectadas; (iii) evidenciar a correção com os formulários de checklist preenchidos e arquivados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a profundidade de sulco estiver abaixo do limite legal (1,6 mm), houver bolha, corte com exposição de lona ou pressão fora da especificação do fabricante.',
  texto_fundamentacao_normativa = 'Os pneus devem apresentar sulco, calibragem e estepe em condições de segurança para circulação, exigência de conservação do veículo estabelecida pelo Código de Trânsito Brasileiro (Lei nº 9.503/1997), sendo o desgaste máximo admitido correspondente à profundidade mínima de sulco de 1,6 mm (indicador TWI). A pressão deve seguir a especificação do fabricante do veículo. O critério "Sulco, pressão, estepe" integra o plano de inspeção da obra e constitui requisito verificável da aderência e da capacidade de resposta do veículo.',
  texto_risco_consequencia = 'Pneus com sulco abaixo do limite legal, pressão inadequada ou danos estruturais reduzem a aderência ao pavimento e elevam o risco de aquaplanagem, estouro e perda de controle, especialmente sob chuva ou carga, podendo resultar em capotamento e colisão. A ausência de estepe em condições de uso impede a substituição segura em caso de pane. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) medir sulco e pressão dos pneus, inclusive do estepe, confrontando com o limite legal e a especificação do fabricante; (ii) substituir os pneus fora de especificação e recalibrar os demais, garantindo estepe apto ao uso; (iii) evidenciar a correção com registro fotográfico dos pneus, sulco e pressão ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a constatação de falha, ruído ou folga anormal no sistema de freios impede a circulação do veículo, devendo este ser recolhido de imediato até reparo e teste aprovado.',
  texto_fundamentacao_normativa = 'O sistema de freios deve estar em perfeito funcionamento, sem ruídos ou folgas anormais, como condição de segurança para circulação do veículo, exigência estabelecida pelo Código de Trânsito Brasileiro (Lei nº 9.503/1997) quanto às condições de conservação e segurança dos equipamentos obrigatórios. O critério "Sem ruídos/folgas anormais" integra o plano de inspeção da obra e constitui requisito verificável da capacidade de frenagem, item de segurança crítico do veículo.',
  texto_risco_consequencia = 'A operação de veículo com freios deficientes compromete a capacidade e o tempo de frenagem, elevando de forma direta o risco de colisão, atropelamento e capotamento, com potencial de lesões graves ou fatais e danos materiais de grande monta. Por se tratar de item de segurança crítico, a permanência da condição mantém o veículo em estado de risco iminente até o efetivo reparo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recolher imediatamente o veículo e submetê-lo a inspeção mecânica do sistema de freios (pastilhas, discos, tambores, fluido e circuito); (ii) executar o reparo por profissional habilitado e realizar teste de frenagem antes de liberar o veículo; (iii) evidenciar a correção com ordem de serviço da manutenção e registro do teste aprovado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o veículo operar em período noturno, em túneis ou sob baixa visibilidade, situações em que a falha de iluminação e sinalização torna a circulação inaceitável.',
  texto_fundamentacao_normativa = 'Faróis, setas (indicadores de direção) e lanternas devem estar todos funcionais, como sistema de iluminação e sinalização obrigatório do veículo, conforme o Código de Trânsito Brasileiro (Lei nº 9.503/1997), que exige o pleno funcionamento desses dispositivos para circulação. O critério "Todos funcionais" integra o plano de inspeção da obra e constitui requisito verificável da visibilidade do veículo e da comunicação de manobras aos demais usuários da via e do canteiro.',
  texto_risco_consequencia = 'A inoperância de faróis, setas ou lanternas reduz a visibilidade do veículo e impede a sinalização de manobras, aumentando o risco de colisão e atropelamento, sobretudo em deslocamentos noturnos, sob chuva ou em áreas de circulação de pedestres e equipamentos no canteiro. A falha mantém o veículo em condição de baixa conspicuidade enquanto não corrigida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) testar individualmente faróis, setas, lanternas e luz de freio, identificando os dispositivos inoperantes; (ii) substituir lâmpadas e reparar o circuito elétrico afetado, restabelecendo o pleno funcionamento; (iii) evidenciar a correção com registro fotográfico dos dispositivos acionados e funcionais ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência do triângulo de sinalização ou do conjunto macaco/chave de roda comprometer a sinalização de pane ou a troca segura de pneu em via.',
  texto_fundamentacao_normativa = 'O veículo deve portar os itens obrigatórios de emergência — macaco, triângulo de sinalização e chave de roda, além de extintor quando aplicável à categoria — conforme os equipamentos obrigatórios definidos pelo Código de Trânsito Brasileiro (Lei nº 9.503/1997) e regulamentação do CONTRAN. Registre-se que a exigência de extintor não se aplica a todas as categorias, o que justifica a ressalva "quando aplicável". O critério integra o plano de inspeção da obra e constitui requisito verificável da capacidade de resposta a panes em deslocamento.',
  texto_risco_consequencia = 'A falta dos itens obrigatórios impede a sinalização adequada do veículo parado por pane e a troca segura de pneu na via, expondo condutor e ocupantes ao risco de atropelamento e de colisão por veículos que se aproximam, e, quando exigível o extintor, à ausência de meio de combate a princípio de incêndio. A deficiência permanece até a reposição dos itens. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a presença e a validade dos itens obrigatórios aplicáveis à categoria do veículo (macaco, triângulo, chave de roda e, quando exigível, extintor); (ii) repor os itens faltantes ou vencidos, acondicionando-os em local acessível; (iii) evidenciar a correção com registro fotográfico dos itens presentes e em condição de uso ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o veículo estiver legalmente obrigado ao tacógrafo e este se encontrar inoperante ou não aferido, ou quando a telemetria for contratualmente exigida e estiver inativa.',
  texto_fundamentacao_normativa = 'Tacógrafo e sistemas de telemetria devem estar funcionais quando exigidos. O tacógrafo é obrigatório para determinadas categorias de veículos conforme o Código de Trânsito Brasileiro (Lei nº 9.503/1997) e a regulamentação do CONTRAN, com aferição periódica pelo órgão metrológico competente; a telemetria, quando prevista, decorre de requisito contratual e do procedimento de gestão de frota da obra. O critério "Funcionais quando exigidos" integra o plano de inspeção e torna verificável o controle de jornada, velocidade e conduta de condução.',
  texto_risco_consequencia = 'A inoperância do tacógrafo, quando exigido, ou da telemetria contratada suprime o registro e o controle de velocidade, jornada e comportamento de condução, favorecendo excessos de velocidade e fadiga do condutor, além de fragilizar a apuração de eventos e a defesa da empresa em autuações e sinistros. A ausência de dados persiste enquanto os sistemas não forem restabelecidos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a exigibilidade do tacógrafo para a categoria do veículo e a previsão contratual de telemetria; (ii) aferir e reparar o tacógrafo junto a oficina credenciada e reativar a telemetria, quando aplicáveis; (iii) evidenciar a correção com certificado de aferição do tacógrafo e/ou tela de operação da telemetria ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Observação — elevar a Menor quando a sujidade acumulada comprometer a visibilidade pelos vidros e retrovisores, a higiene dos ocupantes ou a identificação visual e a sinalização do veículo.',
  texto_fundamentacao_normativa = 'A limpeza e a conservação do interior e da carroceria são requisitos de higiene, preservação do patrimônio e boa apresentação da frota, fundamentados nas boas práticas de gestão de frota e no procedimento de SSMA da obra, sem exigência de norma técnica específica. O critério "Interior e carroceria" integra o plano de inspeção e constitui requisito verificável das condições de conservação do veículo, que também refletem o padrão de cuidado da operação e a legibilidade de identificações e adesivos de segurança.',
  texto_risco_consequencia = 'A falta de limpeza e conservação favorece condições insalubres para os ocupantes, pode obstruir a visibilidade por vidros e retrovisores sujos, acelera a deterioração de componentes e prejudica a legibilidade de identificações e sinalizações do veículo, com reflexo na imagem da obra perante o cliente e a fiscalização. A condição se mantém até a realização da limpeza e dos reparos de conservação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realizar a limpeza do interior e da carroceria e remover resíduos e materiais soltos; (ii) corrigir pontos de conservação (revestimentos, adesivos de identificação e sinalização) e restabelecer a apresentação padrão da frota; (iii) evidenciar a correção com registro fotográfico do veículo limpo e conservado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a existência de ocupante sem cinto de segurança disponível e íntegro, ou a inutilização de banco/ancoragem, deve interromper o transporte até a regularização de todos os postos.',
  texto_fundamentacao_normativa = 'O cinto de segurança é de uso obrigatório por todos os ocupantes do veículo, que devem dispor de cinto íntegro e de banco em condições, conforme o Código de Trânsito Brasileiro (Lei nº 9.503/1997), que impõe o uso do cinto a condutor e passageiros. O critério "Uso obrigatório, bancos íntegros" integra o plano de inspeção da obra e constitui requisito verificável de que cada posição ocupada disponha de contenção eficaz, item de segurança crítico para a proteção dos ocupantes.',
  texto_risco_consequencia = 'A circulação com ocupantes sem cinto disponível ou íntegro, ou com bancos danificados, remove a principal contenção dos ocupantes em caso de colisão ou capotamento, elevando o risco de ejeção e de lesões graves ou fatais. Por se tratar de item de segurança crítico, a permanência da condição mantém os ocupantes desprotegidos a cada deslocamento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a existência, a integridade e o funcionamento do cinto de segurança em cada posição ocupada, bem como a integridade dos bancos e ancoragens; (ii) reparar ou substituir cintos e bancos danificados e exigir o uso do cinto por todos os ocupantes antes do deslocamento; (iii) evidenciar a correção com registro fotográfico dos cintos e bancos íntegros e em uso ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — o transporte de trabalhadores em carroceria ou em veículo não apropriado configura irregularidade grave e deve ser cessado de imediato, mantendo-se a Crítica até a disponibilização de veículo adequado.',
  texto_fundamentacao_normativa = 'O transporte de trabalhadores deve ser feito em veículo apropriado, dotado de assentos fixos e sistema de contenção, sendo vedado o transporte de pessoas em carroceria ou compartimento de carga. A proibição de conduzir pessoas em local não destinado a passageiros decorre do Código de Trânsito Brasileiro (Lei nº 9.503/1997), e a exigência de veículo adequado ao deslocamento de trabalhadores integra o procedimento de SSMA e o plano de gestão de frota da obra. O critério "Veículo apropriado, jamais em carroceria" integra o plano de inspeção de SSMA e constitui requisito verificável e inegociável de segurança no deslocamento de pessoas.',
  texto_risco_consequencia = 'O transporte de trabalhadores em carroceria ou em veículo inadequado expõe as pessoas à queda durante o trajeto, ao esmagamento e à ejeção em freada, colisão ou capotamento, com elevado potencial de lesões graves ou fatais e enquadramento como condição de risco grave e iminente, além de autuação e responsabilização da empresa. A situação permanece crítica a cada deslocamento até a adoção de veículo apropriado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) cessar imediatamente qualquer transporte de trabalhadores em carroceria ou veículo não apropriado; (ii) prover veículo destinado ao transporte de pessoas, com assentos fixos, cintos de segurança e capacidade compatível com o número de trabalhadores; (iii) evidenciar a correção com registro fotográfico do veículo apropriado em uso e com os ocupantes acomodados e cintados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'VE-01' and item_numero = 10;

